/* AC and EC items in developmental order. Ages are in months. "n" is a fixed id; added items carry their source. */
(function(root){const data={"ac":[{"lo":0,"hi":2,"items":[{"n":1,"text":"ينظر الطفل لفترة وجيزة إلى الشخص الذي يتحدث إليه","how":"السؤال للمُرافق: هل ينظر طفلك إلى الشخص الذي يتحدث إليه لثانية واحدة أو أكثر؟ إذا كانت الإجابة نعم، فإلى من ينظر وكم من الوقت يستمر في النظر؟\n\nالإجراء: \nيُطلب من المُرافق أن يحمل الطفل بحيث يتمكن من رؤية وجهه. يتحدث المُرافق إلى الطفل بهدوء وبنغمة صوتية أعلى قليلًا من المعتاد.\n\nالتقييم:  \nينظر الطفل إلى المتحدث لمدة ثانية واحدة.","image":false},{"n":2,"text":"يستمتع باهتمام المُرافق","how":"السؤال للمُرافق: هل يفرح طفلك عندما تحمله، تلعب معه، أو تُعيره الانتباه؟ إذا كانت الإجابة نعم، كيف تعرف ذلك؟\nأوقات شائعة يمكن أن يُلاحظ فيها المُرافق هذا السلوك: بعد الاستحمام أو بعد تناول الطفل للطعام.\nالمواد المطلوبة: لا شيء\n\nالإجراء: \nيُطلب من المُرافق أن يحمل الطفل، يهزه بلطف، يتحدث معه، يغني له، أو يلعب معه.\n\nالتقييم: \nيبتسم الطفل، يُصدر أصواتًا ناعمة، يسترخي، يُظهر زيادة (مثل حركة الذراعين) أو نقصانًا في النشاط الحركي (مثل الهدوء)، يتوقف عن البكاء، أو يُظهر أي تعبير آخر عن الراحة أو السعادة.","image":false},{"n":3,"text":"يستجيب للأصوات غير البشرية في البيئة","how":"السؤال للمُرافق: هل يستجيب طفلك للأصوات التي لا تصدر عن البشر؟ إذا كانت الإجابة نعم، ما هي تلك الأصوات؟ ماذا يفعل طفلك عندما يسمعها؟\n\nأمثلة على الأصوات:\nالموسيقى، جرس الباب، بوق السيارة، المكنسة الكهربائية، إغلاق الباب بعنف، أصوات التلفاز، نباح الكلب.\nالمواد المطلوبة: لعبة تصدر صوتًا عند الضغط\n\nالإجراء: \nيُطلب من المُرافق وضع الطفل في وضعية مريحة على حضنه أو في كرسي الأطفال. بعد ذلك، يتم إصدار صوت مفاجئ أو مرتفع من خلال ضغط اللعبة أو النقر أسفل الطاولة.\n \nالتقييم :\nيُظهر الطفل استجابة للصوت، مثل فتح الفم، رفع الحاجبين، بدء حركة إذا كان ساكنًا، أو التوقف عن الحركة إذا كان نشطًا.","image":false},{"n":4,"text":"ينظر إلى المتحدث لمدة ثانيتين","how":"السؤال للمُرافق: هل ينظر طفلك إليك أو إلى شخص آخر يتحدث لمدة ثانيتين أو أكثر؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\nالمواد المطلوبة: لا شيء\n\nالإجراء: يُطلب من المُرافق أن يحمل الطفل بحيث يتمكن من رؤية وجهه. يُطلب من المُرافق أو أحد الأشقاء التحدث إلى الطفل بنبرة هادئة وبنغمة صوتية مرتفعة قليلاً.\n\nالتقييم :\nينظر الطفل إلى المتحدث بتركيز ويحافظ على التواصل البصري لمدة ثانيتين أو أكثر.","image":false}]},{"lo":3,"hi":5,"items":[{"n":5,"text":"يدير رأسه لتحديد مصدر الصوت","how":"السؤال للمُرافق: هل يدير طفلك رأسه باتجاه مصدر الصوت عندما يسمعه؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\nأمثلة على الأصوات: إغلاق الباب بعنف، جرس الباب، سقوط جسم على الأرض.\n\nالمواد المطلوبة: لعبة تصدر صوتًا عند الضغط\n\nالإجراء: يتم إصدار صوت مرتفع من خلال ضغط اللعبة، أثناء الوقوف إلى جانب الطفل أو خلفه مباشرة (على بُعد يتراوح بين 30 إلى 90 سم تقريبًا). يجب مراقبة الطفل بدقة للتأكد من أن تحريك الرأس يتم بشكل إرادي وليس عشوائيًا.\n\nالتقييم:\nيدير الطفل رأسه لتحديد مصدر الصوت.","image":false},{"n":6,"text":"يستجيب لصوت جديد","how":"السؤال للمُرافق:\nإذا كانت شاشة التلفاز تعمل أو كان هناك أشخاص يتحدثون، هل ينتبه طفلك إلى الأصوات الجديدة في الغرفة؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nأمثلة على الأصوات: صوت المفاتيح، جرس الباب، إغلاق الباب، لعبة موسيقية.\n\nالمواد المطلوبة:\nورقة، مفاتيح مربوطة بسلسلة\n\nالإجراء:\nقم بتجعيد الورقة على بُعد حوالي 10 سم خلف أذن الطفل اليسرى. استمر في إصدار الصوت حتى يتوقف الطفل عن البحث أو الانتباه إليه. بعد ذلك، قم بهزّ المفاتيح بلطف في نفس المكان تقريبًا.\n\nالتقييم:\nيرمش الطفل بعينيه، يُظهر ردة فعل مثل الفزع، يبحث عن مصدر الصوت، أو يُظهر استجابة واضحة أخرى للصوت الجديد.","image":false},{"n":7,"text":"يبحث بنشاط عن الشخص الذي يتحدث","how":"السؤال للمُرافق:\nعندما يتحدث عدة أشخاص بالقرب من طفلك، هل يدير رأسه أو ينظر من شخص إلى آخر أثناء الحديث؟ مثلًا، هل ينظر إلى الشخص المتحدث أثناء الحوار على مائدة الطعام؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nمثال: قد ينظر الطفل إلى الإخوة أو الوالدين أثناء حديثهم في وقت الطعام.\n\nالإجراء:\nيُطلب من المُرافق الجلوس بجانبك وهو يحمل الطفل في حضنه. إذا كان هناك إخوة في الغرفة، يُطلب منهم الجلوس بالقرب أيضًا. تبادل الأدوار في الحديث مع الآخرين وراقب الطفل لترى ما إذا كان ينظر من وجه إلى آخر عند كل متحدث.\n\nالتقييم\nينظر الطفل بنشاط من وجه إلى آخر أو يدير رأسه ليحدد صوت المُرافق أو أحد الإخوة أو صوتك. لا يوجد: ينظر الطفل إلى متحدث واحد فقط، أو ينظر إلى أكثر من متحدث ولكن النظر لا يتزامن مع توقيت الحديث.","image":false},{"n":8,"text":"يضع الأشياء في فمه","how":"السؤال للمُرافق: هل يأخذ طفلك الألعاب أو الأشياء التي تُعطيها له ويضعها في فمه؟ إذا كانت الإجابة نعم، ما نوع الألعاب أو الأشياء؟\n\nالمواد المطلوبة:\nلعبة تصدر صوتًا، خرخاشة\n\nالإجراء: قَدِّم للطفل لعبة نظيفة.\n\nالتقييم:\nيأخذ الطفل اللعبة ويضعها في فمه.","image":false},{"n":68,"text":"يستجيب لتعابير الوجه","how":"السؤال للمُرافق:\nهل يتغير تعبير طفلك أو حركته عندما تبتسم له أو تعبس أمامه؟ يرجى إعطاء مثال.\n\nالإجراء:\nانظر إلى الطفل وابتسم ابتسامة واضحة دون صوت، ثم غيّر تعبيرك إلى العبوس.\n\nالتقييم:\nيتغير تعبير الطفل أو انتباهه أو حركته استجابة لتغير تعبير الوجه.","image":false,"added":true,"source":"ASHA, Communication Milestones 4–6 months: “Responds to facial expressions.”"}]},{"lo":6,"hi":8,"items":[{"n":9,"text":"يهز أو يضرب الأشياء أثناء اللعب","how":"السؤال للمُرافق: هل يقوم طفلك بهز أو ضرب الألعاب أو الأشياء؟ إذا كانت الإجابة نعم، ما هي الألعاب أو الأشياء التي يستخدمها؟\n\nالمواد المطلوبة: خشخاشة، ملعقة، مفاتيح مربوطة، وعاء، لعبة أطفال\n\nالإجراء: ضع أمام الطفل مجموعة من الأشياء مثل لعبة، خرخاشة، ملعقة، مفاتيح، ووعاء. شجعه على اللعب بها. إذا لم يلتقط الطفل أيًا من الألعاب أو الأشياء، قدم له أحدها بيدك.\n\nالتقييم:  \nيهز الطفل أو يضرب واحدة أو أكثر من هذه الأشياء.","image":false},{"n":10,"text":"يتوقع ما سيحدث لاحقًا","how":"السؤال للمُرافق:\nهل يبدو أن طفلك يعرف أن شيئًا ما على وشك الحدوث؟ على سبيل المثال، هل يضحك عندما تبدأ بلعب لعبة مألوفة له مثل: \"أين الطفل؟\"؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال آخر.\n(بديل: لعبة \"Peek-a-boo\")\n\nالإجراء: \nيُطلب من المُرافق أن يلعب مع الطفل لعبة مألوفة لديه، مثل \"أين الطفل؟\"  أو أي نشاط ترفيهي آخر يفعله المُرافق عادةً مع الطفل في المنزل ويعرف أنه يُضحكه أو يُسعده.\n\nملاحظة:\nليست كل الألعاب مألوفة في جميع الثقافات، لذلك يُشجَّع المُرافق على اختيار نشاط ترفيهي معتاد بينه وبين الطفل.\n\nالتقييم :\nيُظهر الطفل أي سلوك يدل على أنه يتوقع ما سيحدث لاحقًا، مثل الضحك قبل بدء اللعبة، رفع ذراعيه أو التمدد عند توقع الحمل، التوقف عن الحركة أو زيادة الانتباه عند التحضير للطعام، أو أي سلوك يشير إلى الترقب.","image":false},{"n":11,"text":"يتوقف عن النشاط عند مناداته باسمه","how":"السؤال للمُرافق:\nعندما ينادي أحدٌ اسم طفلك مرة أو مرتين، هل يتوقف عن اللعب أو إصدار الأصوات وينظر إلى الشخص الذي ناداه؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nالإجراء:\nاجذب انتباه الطفل نحو لعبة أو شيء يثير اهتمامه. اتركه يلعب بمفرده، ثم ناده باسمه مرة أو مرتين كحد أقصى. راقب إذا كان الطفل سيحوّل انتباهه من اللعبة إلى الشخص الذي ناداه باسمه.\n \nالتقييم :\nيتوقف الطفل عن اللعب وينظر أو يتحرك نحو الشخص الذي ناداه باسمه.","image":false}]},{"lo":9,"hi":11,"items":[{"n":12,"text":"يفهم ما يُطلب منه عندما تمد يديك وتقول: \"تعال\"","how":"السؤال للمُرافق: \nهل يتوجه طفلك نحو الأشخاص المعروفين لديه عندما يمدون أيديهم إليه ويقولون: \"تعال\"؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nالإجراء: \nبعد قضاء ما لا يقل عن 10 دقائق مع الطفل والمُرافق، ابتسم للطفل، مد يديك نحوه (راحتا اليدين للأعلى) وقل له: \"تعال\". إذا كان الطفل خجولًا ولم يستجب، يُطلب من شخص مألوف لديه مثل أحد أفراد العائلة أو الأخوة القيام بنفس الإجراء.\n\nالتقييم :\nيتحرك الطفل نحوك أو نحو الشخص الآخر استجابةً للإشارة والكلام.","image":false},{"n":13,"text":"يبحث عن الشيء الذي سقط خارج مجال رؤيته","how":"السؤال للمُرافق:\nهل يبحث طفلك عن شيء سقط من مكانه ولم يعد ظاهرًا، مثل لعبته المفضلة؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nأمثلة: \nيبحث الطفل عن لعبة سقطت من السرير، أو عن طعام، ملعقة، أو وعاء سقط من الكرسي المرتفع.\n\nالإجراء: \nاعرض على الطفل اللعبة أو الشيء، ثم قل \"أُووه!\" أثناء إسقاطه بحيث يحتاج الطفل للبحث عنه. راقب ما إذا كان الطفل سيبحث عنه.\n\nالتقييم : \nيبحث الطفل عن الشيء الذي سقط.","image":false},{"n":14,"text":"يستجيب لكلمة ناهية (مثل \"لا\") دون استخدام الإيماءات","how":"السؤال للمُرافق: ما الكلمة التي تستخدمها لجعل طفلك يتوقف عن فعل شيء؟  \nهل يتوقف طفلك عما يفعله عندما تستخدم هذه الكلمة؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nملاحظة: \nقد ينزعج الطفل عند سماع كلمة \"لا\" ويتوقف عن المشاركة، لذا يُنصح بتقديم هذه المهمة كآخر بند في جلسة التقييم.\nالإجراء: قبل بدء اللعب، يُطلب من المُرافق تحديد الكلمة أو العبارة الناهية التي يستخدمها مع الطفل.\n\nالتقييم :\nيتوقف الطفل عن فعل شيء ما","image":false}]},{"lo":12,"hi":17,"items":[{"n":15,"text":"ينظر إلى الأشياء أو الأشخاص الذين يشير إليهم المُرافق ويسميهم","how":"السؤال للمُرافق: \nعندما تُشير إلى شخص أو شيء وتذكر اسمه، هل ينظر طفلك نحو ذلك الشخص أو الشيء؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nالإجراء: \nيُطلب من المُرافق اختيار بعض الألعاب أو الأشياء أو أفراد العائلة (إن وُجدوا) الذين يعتقد أن الطفل مهتم بهم. تُوضع هذه الأشياء أو الأشخاص في أماكن متفرقة من الغرفة.\n\nيُطلب من المُرافق الإشارة إلى كل شيء أو شخص مع قول: \"انظر إلى (اسم الشيء أو الشخص)\".\n\nالتقييم : \nينظر الطفل إلى الألعاب أو الأشياء أو الأشخاص عندما يُشير المُرافق إليهم ويسميهم.","image":false},{"n":16,"text":"يُظهر اللعب الوظيفي","how":"السؤال للمُرافق: \nهل يلعب طفلك بالأشياء والألعاب كما هو متوقع، مثل دحرجة الكرة؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nاللعب الوظيفي: \nيتمثل في استخدام الطفل للأشياء في اللعب بالطريقة المخصصة لها، مثل تحريك الملعقة في الكوب أو دحرجة الكرة.\n\n- يدحرج الكرة  \n- يكدس المكعبات  \n- يدفع السيارة  \n- يستخدم الملعقة للتحريك  \n\nالتقييم :\nيُظهر الطفل مثالًا واحدًا على استخدام شيء بطريقة مناسبة.","image":false},{"n":17,"text":"يُظهر اللعب الترابطي","how":"السؤال للمُرافق:\nهل يلعب طفلك بأكثر من لعبة أو شيء واحد في الوقت نفسه؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nاللعب الترابطي: \nيحدث عندما يلعب الطفل بجسمين معًا بطريقة استكشافية دون مراعاة الوظيفة، مثل تكديس الأشياء أو وضع جسم داخل آخر.\n\n- تكديس مكعبين أو أكثر  \n- تحريك الملعقة داخل الكوب  \n- تكديس كوبين  \n- دحرجة أو دفع الكرة نحو المكعبات  \n\nالتقييم : \nيُظهر الطفل مثالًا واحدًا على استخدام جسمين معًا في اللعب.","image":false},{"n":69,"text":"يبحث بنظره عند سؤاله «وين؟» عن شيء مألوف","how":"الإجراء:\nدون الإشارة أو النظر إلى الشيء، اسأل الطفل عن شيء مألوف موجود في الغرفة:\n«وين الطابة؟» ثم «وين ماما؟»\n\nالتقييم:\nينظر الطفل حوله أو يبحث عن الشيء في سؤال واحد على الأقل، دون إشارة من الفاحص.","image":false,"added":true,"source":"ASHA, Communication Milestones 13–18 months: “Looks around when asked “where” questions—like “Where’s your blanket?””"}]},{"lo":18,"hi":23,"items":[{"n":18,"text":"يُظهر اللعب التخيلي","how":"السؤال للمُرافق: \nهل يلعب طفلك بألعاب تحاكي العناية الذاتية مثل تمشيط الشعر، الشرب من كوب، أو الأكل بالملعقة؟ إذا كانت الإجابة نعم، يرجى إعطاء مثال.\n\nاللعب الموجه ذاتيًا: \nهو اللعب التخيلي الموجه للذات، مثل محاولة تمشيط الشعر أو التظاهر بالأكل بالملعقة أو الشرب من الكوب.\n \n- تمشيط شعره  \n- تقريب الكوب إلى فمه كما لو يشرب  \n- تقريب الملعقة إلى فمه كما لو يأكل  \n\nالتقييم :  \nيُظهر الطفل مثالًا واحدًا على استخدام الأشياء بشكل مناسب مع توجيه اللعب نحو الذات.\n\nملاحظة: \nإذا أظهر الطفل لعبًا موجهًا نحو الآخرين (مثل إطعام المُرافق أو تمشيط شعر المُرافق)، فالمهارة موجودة لأن اللعب الموجه نحو الآخرين مهارة تتطور لاحقًا.","image":false},{"n":19,"text":"يتبع الروتين والتعليمات المألوفة مع الإشارات الحركية","how":"السؤال للمُرافق: \nهل يتبع طفلك تعليمات بسيطة عندما تساعده بالإشارة أو باستخدام يديك؟\n\nمثال: \nهل يفهم قولك \"اذهب وأحضر حذاءك\" مع الإشارة أو \"أعطني الكوب\" مع مد يدك؟ إذا كانت الإجابة نعم، يرجى ذكر مثالين آخرين.\n\nاعطيني الطابة\nاعطيني ….\n\nالتقييم :\nإجابتان صحيحتان.","image":false},{"n":20,"text":"ينظر إلى الأشياء أو الأشخاص الذين ينظر إليهم المُرافق أو شخص آخر ويشير إليهم دون تسميتهم","how":"الإجراء أ: \nاجلس أمام الطفل وأثِر اهتمامه بلعبة أو نشاط، ثم توقف فجأة عن اللعب، أدر رأسك جانبًا وانظر إلى لعبة أو صورة أو شخص خلف الطفل، وانتظر رد فعل الطفل.\n\nالإجراء ب: \nاستمر في اللعب ثم توقف فجأة، وأشر إلى شيء خلف الطفل وقل: \"انظر!\" دون أن تسمي الشيء أو الشخص المشار إليه.\n\nالتقييم :\nيتبع الطفل نظر وإشارة الفاحص في الإجرائين أ أو ب.","image":false}]},{"lo":24,"hi":29,"items":[{"n":21,"text":"يميز الأشياء المألوفة من بين مجموعة من الأشياء","how":"الإجراء: \nضع مجموعة من العناصر امام الطفل وحافظ على عدد العناصر نفسه خلال التقييم بحيث تستبدل العنصر في حال إجابة صحيحة او تعيد العنصر في حال عدم الإجابة الصحيحة\n\n- \"أين الـ...؟\"  \n- \"أرني الـ...\"  \n\nالتقييم : \nيختار الطفل شيئين بشكل صحيح.","image":false},{"n":22,"text":"يتبع التعليمات مع الإشارات الحركية","how":"العناصر 22 و 23  \nتُقيَّم العناصر 22 و 23 معًا باستخدام نفس الإجراء.\n\nالمواد المطلوبة: \nكتاب، بطة، دمية دب\n\nالإجراء:  \nضع الكتاب، والبطة، ودمية الدب بالقرب من الطفل بحيث يستطيع رؤيتها، ولكن بعيدًا بما يكفي ليحتاج الطفل لتغيير وضعه (مثل الانحناء للأمام، أو القيام من الأرض والمشي إلى الأشياء) للوصول إليها.\n\n١. قل: \"أمسك الكتاب وأحضره هنا، من فضلك.\" ومد يدك لاستقبال الكتاب.  \n٢. عندما يلتقط الطفل الكتاب، ارفع يدك على مستوى الصدر للإشارة إلى التوقف وقل: \"انتظر!\"  \nإذا مد الطفل يده إلى أي شيء غير الكتاب، تابع مع البنود التالية (ج و د) بذكر أي من الأشياء الأخرى التي لم يمتد الطفل إليها، مع منح الدرجة المناسبة.  \n٣. قل: \"كنت أقصد البطة. أمسك البطة وأحضرها هنا، من فضلك.\" ومد يدك لاستقبال البطة.  \n٤. بعد أن يعطيك الطفل البطة، قل: \"الآن أمسك الدمية وأعطها إلى...\"، وأشر إلى شخص في الغرفة وذكر اسمه (مثل الأم أو الأب).\n\nالتقييم :\nإجابة صحيحة واحدة من البنود 1 , 2 , 3 , 4","image":false},{"n":23,"text":"يفهم الكلمات الناهية (غير كلمة \"لا\")","how":"العناصر 22 و 23  \nتُقيَّم العناصر 22 و 23 معًا باستخدام نفس الإجراء.\n\nالمواد المطلوبة: \nكتاب، بطة، دمية دب\n\nالإجراء:  \nضع الكتاب، والبطة، ودمية الدب بالقرب من الطفل بحيث يستطيع رؤيتها، ولكن بعيدًا بما يكفي ليحتاج الطفل لتغيير وضعه (مثل الانحناء للأمام، أو القيام من الأرض والمشي إلى الأشياء) للوصول إليها.\n\n١. قل: \"أمسك الكتاب وأحضره هنا، من فضلك.\" ومد يدك لاستقبال الكتاب.  \n٢. عندما يلتقط الطفل الكتاب، ارفع يدك على مستوى الصدر للإشارة إلى التوقف وقل: \"انتظر!\"  \nإذا مد الطفل يده إلى أي شيء غير الكتاب، تابع مع البنود التالية (ج و د) بذكر أي من الأشياء الأخرى التي لم يمتد الطفل إليها، مع منح الدرجة المناسبة.  \n٣. قل: \"كنت أقصد البطة. أمسك البطة وأحضرها هنا، من فضلك.\" ومد يدك لاستقبال البطة.  \n٤. بعد أن يعطيك الطفل البطة، قل: \"الآن أمسك الدمية وأعطها إلى...\"، وأشر إلى شخص في الغرفة وذكر اسمه (مثل الأم أو الأب).\n\nالتقييم :\nيتوقف الطفل، يسحب يده، أو يتوقف لبرهة قبل محاولة الإمساك بالشيء (انظر البند 2).","image":false},{"n":24,"text":"يميز صورًا لأشياء مألوفة","how":"الإجراء:  \nتمرين : مع المرافق اولا ليعرف الطفل ماالمطلوب منه \nملعقة \nكرة\n\nقل للطفل: \"انظر إلى كل هذه الصور! أشِر إلى...\"  \n\nالقط  \nالبسكويت\nالرضاعة\nالتفاحة  \nالطائر  \nالكوب\n\nالتقييم : \nيميز الطفل أربعة صور صحيحة.","image":true}]},{"lo":30,"hi":35,"items":[{"n":25,"text":"يشارك في اللعب التمثيلي (اللعب الموجّه نحو الآخرين)","how":"تُقيَّم العناصر 25 و 26 معًا باستخدام نفس الإجراء.\n\nالمواد المطلوبة: دمية دب، قطعة قماش، ملعقة، كوب، وعاء، إبريق\n\nالإجراء:  \nضع المواد على الطاولة بالترتيب التالي: دمية الدب، قطعة القماش، الملعقة، الكوب، الوعاء، والإبريق.\nلا توجه الطفل بالإشارة أو تحريك الأشياء نحوه أثناء الحديث.\nقدم الدمية بقولك: \"هذا صديقي السيد الدب. سوف نلعب معه.\"\nتابع التقييم كما يلي:\n\nالسيد الدب جائع. أعطه شيئًا ليأكله.\nالسيد الدب عطشان. أعطه شيئًا ليشربه.\nالسيد الدب نعسان. اجعله ينام.\n\nأمثلة على اللعب التمثيلي:\n- يضع الملعقة في فم الدمية\n- يضع الكوب في فم الدمية\n- يضع الدمية مستلقية ويغطيها بقطعة القماش\n\nالتقييم :\nيشارك الطفل في مثال واحد على اللعب التمثيلي الموجّه نحو الآخرين.\nملاحظة: يمكن تسجيل درجة 1 لهذا البند إذا لوحظ اللعب التمثيلي خلال تقييم بنود أخرى (مثل 27، 28، أو 32).","image":false},{"n":26,"text":"يفهم الأفعال \"يأكل\"، \"يشرب\"، و\"ينام\" في سياقها","how":"تُقيَّم العناصر 25 و 26 معًا باستخدام نفس الإجراء.\n\nالمواد المطلوبة: دمية دب، قطعة قماش، ملعقة، كوب، وعاء، إبريق\n\nالإجراء:\nضع المواد على الطاولة بالترتيب التالي: دمية الدب، قطعة القماش، الملعقة، الكوب، الوعاء، والإبريق.\nلا توجه الطفل بالإشارة أو تحريك الأشياء نحوه أثناء الحديث.\nقدم الدمية بقولك: \"هذا صديقي السيد الدب. سوف نلعب معه.\"\nتابع التقييم كما يلي:\n\nالسيد الدب جائع. أعطه شيئًا ليأكله.\nالسيد الدب عطشان. أعطه شيئًا ليشربه.\nالسيد الدب نعسان. اجعله ينام.\n\nالتقييم :\nيجيب الطفل إجابتين صحيحتين من بين البنود 1 , 2 , 3","image":false},{"n":27,"text":"يفهم الضمائر (-لي، لك)","how":"تُقيَّم العناصر 27 و 28 معًا باستخدام نفس الإجراء.\n\nالمواد المطلوبة: 3 مناديل، 3 أكواب، إبريق صغير\n\nملاحظة:\nلا تقم بالإيماء، النظر، أو الإشارة إلى الأشياء أثناء تقييم البنود الفرعية.\n\nالإجراء:\nضع المناديل على الطاولة بالقرب من الطفل وقل: \"سوف نأكل، من فضلك ساعدني. هذه هي المناديل.\"\n\n١. قل: \"أعطني صحن.\"\n٢. قل: \"أين صحنك؟\" وانتظر رد فعل الطفل\n٣. قل: \"الآن دعنا نشرب شيئًا. اسكب.\"  شجع الطفل على استخدام الإبريق والأكواب.\n٤. بعد أن يصب الطفل المشروبات، قل: \"أين كأسك؟\"\n٥. قل: \"أين كأسي؟\"\n٦. قل: \"ممم... كان لذيذًا! من فضلك ساعدني في ترتيب كل شيء الآن.\"\n\nالتقييم :\nإجابة صحيحة واحدة من البنود 1 , 2","image":false},{"n":28,"text":"يفهم الضمائر (لي، لك) بصيغتها الملكية","how":"تُقيَّم العناصر 27 و 28 معًا باستخدام نفس الإجراء.\n\nالإجراء:\nضع المناديل على الطاولة بالقرب من الطفل وقل: \"سوف نأكل، من فضلك ساعدني. هذه هي المناديل.\"\n\n١. قل: \"أعطني صحن.\"\n٢. قل: \"أين صحنك؟\" وانتظر رد فعل الطفل\n٣. قل: \"الآن دعنا نشرب شيئًا. اسكب.\"  شجع الطفل على استخدام الإبريق والأكواب.\n٤. بعد أن يصب الطفل المشروبات، قل: \"أين كأسك؟\"\n٥. قل: \"أين كأسي؟\"\n٦. قل: \"ممم... كان لذيذًا! من فضلك ساعدني في ترتيب كل شيء الآن.\"\n\nالتقييم :\nإجابة صحيحة واحدة من البنود 4 , 5","image":false},{"n":29,"text":"يميّز أجزاء الجسم الأساسية","how":"المواد المطلوبة: دمية دب\n\nالإجراء:\nاطلب أنت أو المرافق من الطفل تحديد أجزاء جسم الطفل أو المرافق أو دمية الدب باستخدام التعبيرات التي يفضلها الطفل.\nمثل:\n\"أرني...\"\n\"أشر إلى...\"\n\"أين هو/هي...\"\n\"المس...\"\n\nأمثلة على أجزاء الجسم:\nالأنف\nالعين\nاليد\nالأذن\nالرأس\n\nالتقييم :\nيميّز الطفل أربعة أجزاء بشكل صحيح.","image":false},{"n":30,"text":"يميّز الملابس التي يرتديها","how":"الإجراء:\nاطلب من الطفل تحديد ملابسه الخاصة، أو اطلب منه تحديد قطع الملابس المذكورة في البنود التي يرتديها شخص ما في الغرفة، مستخدمًا التعبيرات التي يفضلها الطفل.\n\nأمثلة على العبارات المستخدمة:\n\"أرني...\"\n\"أين هي...\"\n\"أشر إلى...\"\n\"المس...\"\n\nأمثلة على قطع الملابس:\nالحذاء\nالقميص/البلوزة\nالبنطال/الشورت\nالتنورة/الفستان\nأخرى (مثل القبعة ، المعطف )\n\nالتقييم :\nيميّز الطفل ثلاث قطع ملابس بشكل صحيح.","image":false},{"n":31,"text":"يتعرف على الأفعال في الصور","how":"الإجراء:\nقل: \"الآن انظر إلى كل هؤلاء الأطفال. أرني الطفل الذي...\"\n\nالأفعال:\nينام\nيأكل\nيلعب\nيشرب\nيركض\nيستحم\n\nالتقييم :\nيجيب الطفل بشكل صحيح على ثلاثة أفعال.","image":true}]},{"lo":36,"hi":41,"items":[{"n":32,"text":"يتبع الأوامر دون استخدام الإيماءات","how":"المواد المطلوبة: صندوق بغطاء، دمية دب، كوب، ملعقة\n\nالإجراء:\nلا تستخدم الإيماءات عند إعطاء التعليمات.\n\nإذا كانت هذه المرة الأولى التي تقدم فيها الدب للطفل، قدّمها بقول: \"هذا صديقي مستر دب دوب. سوف نلعب معه. انظر إلى هذه الألعاب.\"\n\nضع الدب في الصندوق أمام الطفل، ثم ضع الصندوق والكوب والملعقة على الطاولة.\n\nافتح الصندوق وأعطني دب دوب\nضع دمية الدب على الطاولة وقل: \"خذ الكوب وأعطِ دب دوب بعض العصير.\"\nخذ الملعقة وأعطِ دب دوب بعض الطعام.\n\nالتقييم :\nإجابتان صحيحتان من البنود","image":false},{"n":33,"text":"يفهم استخدام الأشياء","how":"الإجراء:\n\n١. تستخدمها للشرب\n٢. تلبسها في قدمك.\n٣. تُستخدم لطهي الطعام.\n٤. تُستخدم لمشاهدة الفيديوهات (الرسوم المتحركة، الأفلام).\n\nالتقييم :\nيجيب الطفل بشكل صحيح على ثلاثة عناصر.","image":true},{"n":34,"text":"يفهم المفاهيم الكمية (واحدة، بعض، البقية، كل)","how":"العنصران 34 و35: نفِّذهما في نفس الوقت باستخدام نفس الإجراء.\n\nالأدوات: دمية دب، 8 مكعبات في كيس بلاستيكي قابل للإغلاق.\n\n- إذا كانت هذه هي المرة الأولى التي تُعرض فيها الدب على الطفل، قدِّمه بقولك: \"هذا صديقي دب دوب. سنلعب معه.\"\n\nقل: \"قال لي دب دوب إنه جائع جدًا!\"\nاجلس الدب على الطاولة وأظهر كيس المكعبات.\nقل: \"سنلعب ونتخيل أن هذه المكعبات فراولة.\"\nدع الطفل يختار المكعبات من الكيس.\n\n١. “أعطِ دب دوب حبة فراولة واحدة.\"\n٢. “أعطني بعضًا من الفراولة.\"\n٣. “خذ أنت بقية الفراولة.\"\n٤. “لنأكل الفراولة.“ تظاهر بالأكل. *\"ممم!\"*\n٥. “الآن ضع كل الفراولة في الكيس.\"\n\nالتقييم :\nاجابتان صحيحتان من بنود 1 , 2 , 3 , 5","image":false},{"n":35,"text":"يشارك في اللعب الرمزي","how":"العنصران 34 و35: نفِّذهما في نفس الوقت باستخدام نفس الإجراء.\n\nالأدوات: دمية دب، 8 مكعبات في كيس بلاستيكي قابل للإغلاق.\n\n- إذا كانت هذه هي المرة الأولى التي تُعرض فيها الدب على الطفل، قدِّمه بقولك: \"هذا صديقي دب دوب. سنلعب معه.\"\n\nقل: \"قال لي دب دوب إنه جائع جدًا!\"\nاجلس الدب على الطاولة وأظهر كيس المكعبات.\nقل: \"سنلعب ونتخيل أن هذه المكعبات فراولة.\"\nدع الطفل يختار المكعبات من الكيس.\n\n١. “أعطِ دب دوب حبة فراولة واحدة.\"\n٢. “أعطني بعضًا من الفراولة.\"\n٣. “خذ أنت بقية الفراولة.\"\n٤. “لنأكل الفراولة.“ تظاهر بالأكل. *\"ممم!\"*\n٥. “الآن ضع كل الفراولة في الكيس.\"\n\nالتقييم :\nاجابة صحيحة بند 4","image":false},{"n":36,"text":"يفهم المفاهيم المكانية (داخل، على/فوق) بدون إشارات جسدية","how":"المواد: صندوق بغطاء، دمية دب، بطة\n\nالإجراء:  ضع الصندوق المغلق على الطاولة أمام الطفل. امسك الألعاب. قدّم للطفل لعبة واحدة في كل مرة.\n\nهذا دب دوب. ضعه داخل الصندوق.\nهذه بطوطة. ضعيها على الطاولة.\n\nالتقييم :\nإجابتان صحيحتان","image":false}]},{"lo":42,"hi":47,"items":[{"n":37,"text":"يفهم العلاقات بين الجزء والكل","how":"\"انظر إلى هذه الصورة. أرني:\n١. باب السيارة\n٢. أنف الكلب\n٣. ذيل الكلب\n٤. عجلات السيارة\n\nالتقييم :\nثلاث إجابات صحيحة","image":true},{"n":38,"text":"يفهم المفاهيم الوصفية (ثقيل، متشابه)","how":"قل:\n١. هنا صخرة، زهرة، وريشة. أرني أيهما ثقيل.\n٢. أرني الأشياء التي هي متشابهة.\n\nالتقييم:\nإجابة واحدة صحيحة","image":true},{"n":39,"text":"يستنتج المعلومات","how":"١. كان احمد يلعب في الخارج وتبللت حذاؤه. كيف تعتقد أن حذاء علي تبلل؟\n٢. حلا أُصيبَت في ركبتيها وكوعيها. كيف تعتقد أنها أُصيبت؟\n٣. كانت سالي جائعة جدًا عندما عادت إلى المنزل بعد المدرسة. ماذا تعتقد أن سالي فعلت عند وصولها إلى المنزل؟\n\nالتقييم :\nإجابتان صحيحتان","image":true},{"n":40,"text":"يفهم الجمل المنفية","how":"١. أرني الطفل الذي لا ينام\n٢. أرني العش الذي لا يحتوي على بيض.\n٣. أرني الطفل الرضيع الذي لا يبكي\n\nالتقييم :\nإجابتان صحيحتان","image":true},{"n":70,"text":"يتعرف على العلامات والشعارات المألوفة","how":"الإجراء:\nاعرض على الطفل علامات يراها في بيئته، مثل إشارة «قف» وشعار محل أو منتج يعرفه. اسأل: «شو هاد؟» أو «شو يعني؟»\n\nالتقييم:\nيتعرف على علامتين، بالاسم أو بذكر معناها. لا يُشترط أن يقرأ الكلمات.","image":false,"added":true,"source":"ASHA, Communication Milestones 3–4 years: “Recognizes signs and logos like STOP.”"}]},{"lo":48,"hi":53,"items":[{"n":41,"text":"يفهم الرغبات المختلفة","how":"الإجراء: مرر الدب على الطاولة وقل:\n\nها هو دب دوب قادم. حان وقت الطعام وهو جائع.\nضع صورة البيتزا والسندويش.\nيمكنه أن يأكل البيتزا أو السندويش. أرني أيهما تفضل أكثر؟\nأعلم أنك تفضل (اذكر اسم الطعام الذي يختاره الطفل) ولكن دون أوسيتو فعلاً يحب (اذكر اسم الطعام الذي لم يختاره الطفل).\nأرني أيهما سيأكل دب دوب؟\n\nالآن دب دوب مستعد لشيء حلو.\nاعرض صورة الآيس كريم والبسكويت. يمكنه الاختيار بين الآيس كريم أو البسكويت.\nأرني أيهما تحب أكثر؟\nأعلم أنك تفضل (اذكر اسم الطعام الذي يختاره الطفل) ولكن دب دوب فعلاً يحب (اذكر اسم الطعام الذي لم يختاره الطفل).\nأرني أيهما سيأكل دب دوب؟\n\nالتقييم :\nإجابتان صحيحتان\n\nملاحظة: لا يحتاج الطفل إلى نطق الكلمة للحصول على التقييم، فالإشارة إليها في كافية لمنحه الدرجة.","image":true},{"n":42,"text":"يفهم المفاهيم الوصفية النوعية (طويل، قصير)","how":"انظر إلى هذه الحيوانات. أي منها لديه رقبة طويلة؟\nانظر إلى هؤلاء الأطفال وهم يجمعون التفاح. أي طفل طويل؟\nهؤلاء الأطفال لديهم حبال نط. أرني الحبل القصير.\n\nالتقييم :\nإجابتان صحيحتان","image":true},{"n":43,"text":"يفهم الضمائر (هي، هو، هم)","how":"١. هي على السلم.\n٢. هو في المي.\n٣. هم في المي.\n\nالتقييم :\nإجابتان صحيحتان","image":true}]},{"lo":54,"hi":59,"items":[{"n":44,"text":"يفهم الجمل التي تحتوي على توضيح بعد الاسم","how":"تمرين: انظر إلى هذه الصورة. أشِر إلى كل قطة وقل: هذا الهِرُّ الأسود، وهذا الهِرُّ البرتقالي، وهذا الهِرُّ الأبيض.\n\nأرني القط البرتقالي.\nأرني القط الأسود.\nأرني القط الأبيض.\n\nأرني...\n- القط الأبيض الذي ينام.\n- قط صغير ليس أسود.\n- القط الأبيض والصغير الموجود برا الصندوق.\n\nالتقييم :\nإجابتان صحيحتان","image":true},{"n":45,"text":"يحدد فئات الأشياء في الصور","how":"الإجراء: اطلب من الطفل تحديد جميع الاستجابات المستهدفة.\nملاحظة: إذا لم يشِر الطفل إلى جميع الاستجابات المستهدفة، اسأله: هل هذا كل شيء؟\nإذا شمل رد الطفل استجابة غير صحيحة، لا تقم بتصحيحها.\n\nقل:\n\"انظر إلى جميع الصور: كلب، تفاحة، قطة، كرسي، سرير، آيس كريم، حصان، وكعكة.\"\n\nأرني...\n- جميع الحيوانات. (الكلب، القطة، الحصان)\n- كل ما هو طعام. (التفاحة، الآيس كريم، الكعكة)\n\nقل:\n\"الآن انظر إلى جميع الصور: دمية، شورت، كرة، فراولة، قميص، فستان، دب، وبرتقال.\"\n\nأرني...\n- كل الأشياء التي نرتديها. (الشورت، الفستان، القميص)\n- كل الألعاب. (الكرة، الدمية، الدب)\n\nالتقييم :\nثلاث فئات صحيحة","image":true},{"n":46,"text":"يحدد الألوان","how":"ملاحظة:\nإذا كان الطفل يعاني من عمى ألوان جزئي أو كلي، فلا يُتوقع منه التعرف على الألوان المعروضة في هذا البند. لا تُطبق هذا البند ولا تُحتسب ضمن قاعدة التوقف.\n\nالمواد:\n8 أقلام تلوين (أحمر، أصفر، أزرق، أخضر، أسود، بني، برتقالي، بنفسجي)\n\nالإجراء: وزّع الأقلام الشمعية على الطاولة.\n\nقل:\nانظر إلى الأقلام الشمعية.\n\nأرني اللون...\n- الأحمر\n- البرتقال\n- الأصفر\n- البنفسجي\n- الأخضر\n- الأزرق\n\nالتقييم :\nأربع إجابات صحيحة","image":true},{"n":71,"text":"يفهم المفاهيم المكانية (خلف، بجانب، بين)","how":"المواد: مكعبان ولعبة صغيرة.\n\nالإجراء:\nدون الإشارة، قل:\n١. «حط اللعبة خلف المكعب.»\n٢. «حط اللعبة جنب المكعب.»\n٣. «حط اللعبة بين المكعبين.»\n\nالتقييم:\nإجابتان صحيحتان.","image":false,"added":true,"source":"ASHA, Communication Milestones 4–5 years: “Understands and uses location words, like behind, beside, and between.”"},{"n":72,"text":"يتبع قواعد بسيطة في لعبة","how":"الإجراء:\nاشرح لعبة بالكلام فقط: «لما بقول طابة، بتصفق. لما بقول كرسي، ما بتتحرك.» جرّب مرة، ثم قل الكلمتين بترتيب مختلف أربع مرات.\n\nالتقييم:\nيتبع القاعدة في ثلاث مرات من أربع.","image":false,"added":true,"source":"ASHA, Communication Milestones 4–5 years: “Follows simple directions and rules to play games.”"},{"n":73,"text":"يميّز الكلمات المتناغمة","how":"تمرين: «باب، ناب: متل بعض بالآخر. باب، قلم: مو متل بعض.»\n\nالسؤال: هل هاتان الكلمتان متشابهتان في الآخر؟\n١. نار، دار\n٢. بيت، كلب\n٣. سوق، فوق\n٤. شمس، موز\n\nالتقييم:\nثلاث إجابات صحيحة.","image":false,"added":true,"source":"ASHA, Communication Milestones 4–5 years: “Identifies some rhyming words, like cat and hat.” CDC/AAP (Zubler et al., 2022), by 5 years: “Uses or recognizes simple rhymes (bat-cat, ball-tall)”"}]},{"lo":60,"hi":65,"items":[{"n":47,"text":"يفهم الأسماء المعدلة","how":"(تدريب) قل: أريدك أن تنظر إلى كل الكلاب. أرني الكلب البني الكبير.\n\nتقدّم المساعدة فقط في مرحلة التدريب. لا تقدم مؤشرات إضافية أثناء التطبيق.\n\nقل: أرني...\n- الكلب الأسود الصغير. إذا أشار الطفل إلى الكلب الأسود الصغير ذو البقع، اسأل: هل يوجد كلب أسود صغير آخر؟\n- الكلب الأبيض الكبير. إذا أشار الطفل إلى الكلب الأبيض الكبير ذو البقع، اسأل: هل يوجد كلب أبيض كبير آخر؟\n- الكلب الصغير ذو البقع.\n\nالتقييم :\nإجابتان صحيحتان","image":true},{"n":48,"text":"يفهم الجمل المركبة","how":"تدريب\n- كانت سارة حزينة لأن دراجتها كانت ذات إطار مثقوب ولم تستطع الذهاب للنزهة.\n- أثناء عودتها إلى المنزل، رأت سارة كلبًا ذا بقع بيضاء.\n- عندما استيقظت، وجد الطفلة دميتها على الأرض.\n- لأن الجو كان باردًا في الخارج، ارتدى الطفل سترة وأغلق النافذة.\n\nالتقييم :\nإجابتان صحيحتان","image":true},{"n":49,"text":"يفهم المفاهيم الكمية (كل، جميع)","how":"كل | حيوان. (زرافة، قرد، نمر، فيل)  ) كل حيوان / كل | حيوان )\nجميع الألعاب. (شاحنة، كرة، مكعبات، دمية)\n\nالتقييم :\nإجابتان صحيحتان","image":true}]},{"lo":66,"hi":71,"items":[{"n":50,"text":"يميّز الصورة التي لا تنتمي إلى المجموعة","how":"تمرين: انظر إلى هذه الصور: لون، قلم رصاص، مسطرة، قلم. أرني الصورة التي لا تنتمي إلى البقية. (المسطرة)\n\n١. خيارة، كنزة، بنطال، فستان (خيارة)\n٢. تفاحة، إجاصة، مي، برتقانة (مي)\n٣. سكين، ملعقة، مشك، شوكة (شوكة)\n\nالتقييم :\nإجابتان صحيحتان","image":true},{"n":51,"text":"يميّز الأصوات الأولية","how":"تمرين: كلب، حبل، لمبة، بصل | صوت الأول —> ب\n\n١. نحلة، فجل، باب، شورت | —> ن\n٢. ساعة، تخت، بطن، عنب | —> س\n٣. نسر، كلب، نملة، قمر، كباب، موزة، سلة، يد | —> ك\n\nالتقييم :\nإجابتان صحيحتان","image":true},{"n":52,"text":"يفهم المفاهيم الكمية (بعض، نصف، كامل)","how":"١. بعض الذرة\n٢. نصف ذرة\n٣. ذرة كاملة\n\nالتقييم :\nإجابتان صحيحتان","image":true}]},{"lo":72,"hi":83,"items":[{"n":53,"text":"يظهر مهارات القراءة الناشئة من خلال التعامل مع الكتاب ومفهوم الكلمة","how":"المواد: 2 كتب قصص\n\nعرّف الطفل على الكتابين\nقل: \"انظر إلى كتبي. هذا الكتاب يتحدث عن… و هذا الكتاب يتحدث عن...\"\n\nبعد اختيار الطفل للكتاب، أزل الكتاب الآخر من أمامه.\nأعطِ الطفل الكتاب مقلوبًا بحيث تكون الغلاف الخلفي للأعلى، وقل:\n\n“خذ، الآن أمسِك الكتاب.\"\n\"لننظر في الكتاب.\"\n\"أرني الغلاف.\"\n\"أرني صفحة في الكتاب.\"\n\"أشر إلى كلمة في هذه الصفحة.\"\n\nالتقييم :\nأربع إجابات صحيحة","image":false},{"n":54,"text":"يفهم مفاهيم الزمن والتتابع (الأخير، الأول)","how":"\"انظر! هذه الصور تُظهر ولدًا يستحم. ملأ الولد حوض الاستحمام بالماء. غسل وجهه وجسمه. لعب بألعابه. ثم خرج من الحوض وجفف نفسه.\"\n\nما الذي فعله الولد في النهاية؟\nما الذي فعله الولد أولًا؟\n\nالتقييم :\nإجابتان صحيحتان","image":true},{"n":55,"text":"يفهم المعتقدات الخاطئة (نظرية العقل)","how":"المواد: دمية دب، صندوق بغطاء، كرة\n\nالإجراء:\nقل: ”دب دوب يلعب بكرتِه المفضلة. عليه أن يذهب لتناول الطعام، لذلك وضع كرته داخل هذا الصندوق، حتى لا تتدحرج ويتمكن من إيجادها لاحقًا للعب مرة أخرى.\"\nاجعل الدمية تضع الكرة داخل الصندوق وأعد الغطاء. ضع الدمية خلفك.\n\nقل: ”دب دوب ذهب لتناول الطعام! سأحرّك الكرة وأضعها تحت الطاولة.\"\nأخرج الكرة من الصندوق وضعها تحت الطاولة، أو على الأرض.\nحرّك الدمية من خلفك وقل: \"أوه لا! ها ودب دوب قادم!\"\n\nأين سيبحث عن كرته؟ (داخل/في الصندوق)\nلماذا سيبحث هناك؟ (لأنّه وضعها هناك)\n\nأمثلة على الإجابات الصحيحة:\nلأنه وضعها هناك\nلأنها كانت هناك \nلأنّه تركها هناك\n\nالتقييم :\nإجابتان صحيحتان","image":false},{"n":56,"text":"استدعاء تفاصيل القصة","how":"قل: \"هذه قصة عن طفلين وكلبهما لولو. استمع للقصة. أريدك أن تخبرني بها بعد أن أنهي.\"\n\nاحمد ومايا لديهما كلب اسمه لولو. كان لولو يحب النوم بجانب الباب على بطانية زرقاء قديمة\nفي إحدى الليالي، كانت تمطر بغزارة. لقد بلل المطر الكلب لولو بالكامل!  \nقال احمد لأخته: \"لولو يبتل تحت المطر. ماذا يمكننا أن نفعل لكي لا يبتل؟\"\nقرر احمد ومايا صنع بيت صغير للكلب. في اليوم التالي، وجدا صندوقاً كبيراً يمكنهما استخدامه.  \nعملا بجد لصنع البيت المثالي. قطع احمد باباً في الصندوق، ثم وضعا قطعة من المعدن كسقف للبيت.  \nعندما انتهيا، هرب لولو. قالت مايا: \"أعتقد أنه لم يعجبه.\"  \nلكنه عاد حاملاً بطانيته الزرقاء القديمة ووضعها داخل بيته الصغير.  \nالآن، عندما تمطر، يكون لولو جافاً ودافئاً وسعيداً في بيته الجديد.\n\nما لون بطانية لولو؟ (أزرق)\n\nالتقييم :\nيحدد الطفل اللون الصحيح.","image":true},{"n":57,"text":"تحديد الفكرة الرئيسية","how":"ما المشكلة التي يعاني منها الكلب لولو؟\n\nالتقييم :\nيحدد الطفل الفكرة الرئيسية أو المشكلة.","image":true},{"n":58,"text":"تحديد تسلسل الأحداث في القصة","how":"ما أول شيء يفعله احمد ومايا لحل المشكلة؟\n\nالتقييم :\nيحدد الطفل ما تم القيام به أولاً لحل المشكلة.","image":true},{"n":59,"text":"استنتاج","how":"كيف تعتقد أن الكلب يشعر تجاه بيته الجديد؟\n\nالتقييم :\nيحدد الطفل شعور منطقي","image":true},{"n":60,"text":"التنبؤ","how":"ماذا تعتقد أن الكلب سيفعل في المرة القادمة التي تمطر فيها؟\n\nالتقييم :\nيقوم الطفل بتنبؤ منطقي.","image":true}]},{"lo":84,"hi":95,"items":[{"n":61,"text":"يفهم المفاهيم الكمية (متساو، أقل شي)","how":"هنا فتاة صغيرة لديها ثلاث بالونات (أشر).\nأرني الفتاة التي لديها نفس عدد البالونات.\nأي فتاة لديها أقل عدد من البالونات؟\n\nالتقييم :\nإجابتان صحيحتان.","image":true},{"n":62,"text":"يفهم مفهوم القلة (قليل/شوي)","how":"الطبق الذي يحتوي على قليل من البسكويت.\nالصورة التي تحتوي على عدد قليل من الدببة.\n\nالتقييم :\nإجابتان صحيحتان.","image":true},{"n":63,"text":"يفهم مفاهيم الوقت (الفصول)","how":"الشتاء\nالخريف\nالصيف\nالربيع\n\nالتقييم :\nثلاث إجابات صحيحة.","image":true},{"n":64,"text":"يصحح القواعد النحوية","how":"انا آكل —> صح\nهي يبكي —> هو يبكي\nعصفور لونا صفرا —> عصفور لونو اصفر\nولد تلعب مع قطة —> ولد يلعب مع قطة\nولد يلعب بالشاحنات —> ولد يلعب بالشاحنة\nبنت تبكي لان المكعبات يوقع —> يوقعوا\n\nملاحظة :\nالطفل عليه الاشارة على صح او الخطآ فقط دون انتاج\n\nالتقييم:\nأربع إجابات صحيحة","image":true},{"n":65,"text":"إظهار مهارات القراءة الناشئة من خلال التعامل مع الكتاب والوعي بالطباعة","how":"المواد : قصة\n\nاسم المؤلف.\nعنوان الكتاب.\nمن كتب هذا الكتاب.\nاقلب إلى صفحة في الكتاب وقل: \"أرني...\"\nالمكان الذي سأبدأ منه القراءة في هذه الصفحة.\nالمكان الذي سأنهي القراءة فيه في هذه الصفحة.\n\nالتقييم :\nأربع إجابات صحيحة","image":false},{"n":66,"text":"اتباع تعليمات متعددة الخطوات","how":"تمرين : ضمن الغرفة مع الوسائل المتوفرة\n\nامثلة :\n“قم من الكرسي، ارفع يديك للأعلى، ثم التفت إلى اليمين.“\n\"خذ المكعب الأخضر، ضعه فوق المكعب الأصفر، ثم اضغط عليه بإصبعك.“\n\"ارسم دائرة، لونها بالأحمر، ثم اكتب اسمك بجانبها.“\n\"افتح العلبة، أخرج القلم، ثم ضعه على الطاولة.\"\n\nمعايير التقييم:\nالانتباه والتركيز\nالفهم اللغوي\nالذاكرة السمعية\nالتنفيذ بالتسلسل\n\nالتقييم :\nثلاث صحيحة","image":false},{"n":67,"text":"تحديد كلمة لا تنتمي إلى فئة دلالية","how":"تدريب :\nسأقول مجموعات من الكلمات. إحداها لا تنتمي إلى المجموعة. استمع للكلمات وأخبرني أي كلمة لا تنتمي:\nأصفر، أخضر، أزرق، أكل. (أكل)\nإذا لم يجيب الطفل بشكل صحيح، قل: الكلمة التي لا تنتمي هي \"أكل\" لأنها ليست لونًا.\n\nدائرة، باب، كرة، برتقالة (باب)\nتفاحة، حليب، عصير، ماء (تفاحة)\nورق، ممحاة، كتاب، قصة (ممحاة)\nنجم، كرسي، شمس، مصباح (كرسي)\n\nالتقييم :\nثلاث إجابات صحيحة","image":true}]}],"ec":[{"lo":0,"hi":2,"items":[{"n":1,"text":"وجود منعكس المص والبلع","how":"زجاجة رضاعة بحلمة أو لهاية يقدّمها المُعتني\nالتقييم : يُظهر تسلسلاً منسقًا بين المصّ والبلع؛ دون سعال أو اختناق أو سكب","image":false},{"n":2,"text":"يُصدر أصواتًا من الحنجرة","how":"ضع الطفل مستلقياً على ظهره وتحدث إليه.\nالتقييم : يُصدر أصواتًا رخوة، حنجريّة، غَرغَرية","image":false},{"n":3,"text":"يُغيّر نغمة أو مدة أو شدة البكاء","how":"هل يبكي طفلك أحيانًا بقوة وأحيانًا برقة؟\nالتقييم : يُصدر أصواتًا أو يبكي مع تنوّع في النغمة أو المدة أو الشدة","image":false}]},{"lo":3,"hi":5,"items":[{"n":4,"text":"يستجيب للمتحدث بالابتسام","how":"هل يبتسم طفلك للأشخاص عندما يتحدثون إليه؟\nالتقييم : يبتسم استجابةً لاقتراب المتحدث منه أو حمله أو التحدث إليه","image":false},{"n":5,"text":"يُصدر أصواتًا تُعبّر عن المتعة والانزعاج","how":"هل يصدر طفلك أصواتًا عندما يكون سعيدًا \nومرتاحًا تختلف عن الأصوات التي يصدرها عندما يكون متعبًا أو منزعجًا أو غير سعيد؟\nالتقييم : يُصدر صوتين صحيحين (واحد للتعبير عن المتعة وآخر للتعبير عن الانزعاج)","image":false},{"n":6,"text":"يُصدر أصواتًا عند التحدث إليه، مع تحريك الذراعين والساقين أثناء إصدار الأصوات","how":"هل يصدر طفلك أصواتًا ويحرك ذراعيه ورجليه عندما يتحدث إليه أحدهم؟\nالتقييم :  تُرافق الأصوات حركات لا إرادية مثل خفق الذراعين أو تحريك الساقين","image":false},{"n":62,"text":"ينفخ بشفتيه محدثاً صوت اهتزاز","how":"السؤال للمُرافق:\nهل يصدر طفلك صوتاً بنفخ الهواء بين شفتيه أو مع إخراج لسانه؟\n\nالتقييم:\nيصدر الصوت تلقائياً أو تقليداً، حسب إفادة المُرافق أو بالملاحظة.","image":false,"added":true,"source":"ASHA, Communication Milestones 4–6 months: “Blows “raspberries.”” CDC/AAP (Zubler et al., 2022), by 6 months: “Blows “raspberries” (sticks tongue out and blows)”"}]},{"lo":6,"hi":8,"items":[{"n":7,"text":"يضع الأشياء في فمه","how":"يُعبّر عن الرفض بالإشارة أو الصوت\nأمثلة على سلوكيات الاعتراض\nالتمدد نحو الشيء، دفع الشخص بعيدًا، هز الرأس بمعنى لا\nتحريك الرأس أو الجسم بعيدًا عن الوصي، الإمساك باللعبة بإحكام،البكاء\nالتقييم : يظهر الطفل سلوك اعتراض واحد على الأقل أو يصدر صوت اعتراض","image":false},{"n":8,"text":"يُحاول تقليد تعبيرات الوجه والحركات","how":"هل يحرك طفلك شفتيه أو لسانه عندما تصنع وجوهًا مضحكة أو تحرك شفتيك ولسانك؟\nالتقييم: يُحاول تحريك وجهه أو لسانه استجابةً لتعبيرات وحركات وجه المُعتني.","image":false},{"n":9,"text":"يُصدر صوتين مختلفين من أصوات الصوامت","how":"هل يصدر طفلك أصواتًا مختلفة مثل /ب/ و /م/؟\nالتقييم: يُنتج صوتين مختلفين واضحين من أصوات الصامتة.","image":false},{"n":10,"text":"يُصدر صوتين مختلفين من أصوات الصوائت","how":"هل يصدر طفلك أصواتًا مختلفة مثل /ا/ و /و/؟\nالتقييم: يُنتج صوتين مختلفين واضحين من أصوات الصوائت.","image":false},{"n":63,"text":"يرفع ذراعيه ليُحمل","how":"السؤال للمُرافق:\nعندما يريد طفلك أن تحمله، هل يرفع ذراعيه نحوك؟\n\nالإجراء:\nقف أمام الطفل وانتظر قليلاً دون مدّ يديك.\n\nالتقييم:\nيرفع ذراعيه طلباً للحمل، بالملاحظة أو حسب إفادة المُرافق.","image":false,"added":true,"source":"ASHA, Communication Milestones 7–9 months: “Raises arms to be picked up.” CDC/AAP (Zubler et al., 2022), by 9 months: “Lifts arms up to be picked up”"},{"n":64,"text":"يدفع الشيء الذي لا يريده","how":"الإجراء:\nقدّم للطفل شيئاً لا يهتم به، أو أعد تقديم لعبة تركها.\n\nالسؤال للمُرافق:\nماذا يفعل طفلك عندما يُعطى شيئاً لا يريده؟\n\nالتقييم:\nيدفع الشيء أو يبعده بيده ليعبّر عن الرفض.","image":false,"added":true,"source":"ASHA, Communication Milestones 7–9 months: “Pushes away unwanted objects.”"}]},{"lo":9,"hi":11,"items":[{"n":11,"text":"يدمج بين الأصوات","how":"هل يصدر طفلك صوتين معًا، مثل \"با\" أو \"با\"؟\nالتقييم: يُصدر تركيبة صوتية أو مقطعًا لفظيًا (V-V, C-V, or V-C)\nأمثلة على استجابات صحيحة:\n- متحرك-متحرك (V-V): آه-إي، أو-أوه\n- حرف ساكن-حرف متحرك (C-V): با، ما، دا، دو، تي\n- حرف متحرك-حرف ساكن (V-C): آخ، أب، أم\nأمثلة على استجابات غير صحيحة:\n- تكرار الحروف الساكنة فقط: ب-ب-ب-ب (مثل إصدار صوت فرقعة الشفاه)\n- إطالة الصوت المتحرك: آآآآآه\n- إطالة الصوت الساكن: م-م-م-م","image":false},{"n":12,"text":"يسعى لجذب انتباه الآخرين","how":"هل يحاول طفلك لفت انتباهك؟\nالتقييم: الطفل يبذل جهدًا لجذب أو الحفاظ على الانتباه.","image":false},{"n":13,"text":"يلعب ألعابًا بسيطة مع شخص آخر مع استخدام التواصل البصري المناسب","how":"شارك الطفل في نشاط لعب تفاعلي مثل وضع الأشياء داخل الصندوق وخارجه\nالتقييم: يشارك في اللعب مع شخص آخر مع الحفاظ على التواصل البصري المناسب\nأمثلة على استجابات صحيحة:\n- الطفل يلعب (peek-a-boo) مع استخدام التواصل البصري المناسب.","image":false}]},{"lo":12,"hi":17,"items":[{"n":14,"text":"يستخدم إيماءة تمثيلية (رمزية)","how":"هل يلوح طفلك بيده ليقول وداعًا (باي-باي)؟\nهل يصفق طفلك بيديه ليُظهر أنه سعيد أو فخور بشيء فعله، مثل رمي الكرة؟\nالتقييم: يستخدم إيماءة رمزية واحدة.\n(مثال: يلوّح للوداع، يصفق، يحرك جسده)","image":false},{"n":15,"text":"يُصدر الطفل مقاطع صوتية مكونة من مقطعين","how":"العب مع الطفل لاستثارة إنتاج تركيبات مكونة من مقطعين.\nإذا أظهر الطفل اهتمامًا بالفقاعات، انفخ الفقاعات.\nقل تراكيب من مقطعين مع انفجار كل فقاعة.\nالتقييم:\nيُصدر مقطعًا مكونًا من مقطعين (مثل: ماما، بابا).","image":false},{"n":16,"text":"يتبادل الأدوار الصوتية عدة مرات","how":"عندما تقلد صوتًا يصدره طفلك، هل يعيد الطفل الصوت الذي قمت به؟\nهل يتبادل معك الأدوار صوتيًا مرتين أو ثلاث مرات؟\n\nالتقييم:\nأخذ الطفل على الأقل دورتين للتواصل الصوتي ردًا على تقليد الوصي لأصوات الطفل.","image":false},{"n":17,"text":"يُنتج سلاسل صوتية (مقطعين إلى ثلاثة) بإيقاع يشبه كلام الكبار","how":"المواد: ألعاب وأشياء أبدى الطفل اهتمامًا بها مسبقًا\nالتقييم: يُنتج سلسلة مكونة من مقطعين إلى ثلاثة مقاطع بصوتية وإيقاع مشابه لكلام الكبار\nحرف ساكن - حرف متحرك (C-V) (لا)\nحرف ساكن - حرف متحرك - حرف ساكن (C-V-C) (مين)\nحرف ساكن - حرف متحرك - حرف ساكن - حرف متحرك (C-V-C-V) (بابا)\nأنواع أخرى","image":false},{"n":18,"text":"يُصدر خمس آصوات مختلفين من الاصوات الصامتة (?  b d m n )","how":"التقييم: يصدر الطفل خمس أصوات ساكنة مختلفة","image":false},{"n":19,"text":"يستخدم كلمة واحدة على الأقل","how":"المواد:\nألعاب وأشياء أبدى الطفل اهتمامًا بها مسبقًا.\n\nالتقييم:\nيُظهر استخدامًا ذا معنى لكلمة واحدة.\nلكي تُعتبر الكلمة ذات معنى، يجب أن تُستخدم تركيبة الصوت ككلمة بشكل متكرر.\nويجب أن تكون في سياق تواصلي مناسب.\nلا يشترط أن يكون النطق دقيقًا أو مطابقًا للكلمة.","image":false}]},{"lo":18,"hi":23,"items":[{"n":20,"text":"يستخدم الإيماءات والصوتيات لطلب الأشياء","how":"ضع اثنين أو ثلاثة أشياء بالقرب من الطفل ولكن بعيدًا عن متناوله.\nقل: \"انظر إلى هذه الأشياء\".\nراقب الطفل لترى إذا كان يشير إلى الشيء أو يحاول الوصول إليه ويصدر صوتًا لطلبه.\n\nالتقييم:\nيُظهر حالة يستخدم فيها الإيماءة والصوت لطلب شيء.\n\nأمثلة على الإجابات غير الصحيحة:\n- الطفل يشير أو يستخدم إيماءة بدون أصوات.\n- الطفل يصدر أصواتًا (مثل البكاء) بدون أن يشير أو يستخدم إيماءة لما يريد.\n- الطفل يصل إلى الشيء ويصدر صوتًا.","image":false},{"n":21,"text":"يُشارك في نشاط لعب روتيني مع شخص آخر لمدة دقيقة واحدة على الأقل، مع الحفاظ على تواصل بصري مناسب","how":"المواد:\nساعة توقيت أو ساعة عقارب.\n\nالتقييم:\nيُشارك بانتباه ويحافظ على تواصل بصري لمدة دقيقة واحدة.","image":false},{"n":22,"text":"يمد اللعبة أو يشير إلى شيء ليُظهره للآخرين","how":"هل يشير طفلك إلى الألعاب أو الأشياء الأخرى ليُظهرها لك؟\n\nضع الأشياء في متناول الطفل.\nاطلب من الوصي أن يُظهر للطفل أحد الأشياء.\nراقب إذا كان الطفل يشير إلى شيء آخر أو يُعطي شيئًا للوصي كما لو كان يُريه إياه.\n\nالتقييم:\nيجذب الطفل الانتباه إلى شيء ما عن طريق الإشارة أو العرض.","image":false},{"n":23,"text":"يستخدم خمس كلمات على الأقل","how":"أثناء اللعب مع الطفل، أشر إلى الأشياء واسأله: \"ما هذا؟\"\n\nالكلمات التي نطقها الطفل:\n\nالتقييم:\nيُنتج خمس كلمات أو أكثر.","image":false},{"n":65,"text":"يجمع كلمتين معاً","how":"الإجراء:\nالعب مع الطفل، وسجّل ما يقوله. اسأل المُرافق عن أمثلة من البيت.\n\nأمثلة: «كمان مي»، «ماما تعي»، «باي بابا».\n\nالتقييم:\nيجمع كلمتين مختلفتي المعنى مرتين على الأقل. لا تُحسب العبارات المحفوظة ككتلة واحدة.\n\nملاحظة: يختلف عن البند «يستخدم تراكيب لفظية مختلفة»، الذي يتطلب أنواعاً محددة من التراكيب.","image":false,"added":true,"source":"ASHA, Communication Milestones 19–24 months: “Puts two or more words together—like more water or go outside.” CDC/AAP (Zubler et al., 2022), by 24 months: “Says at least 2 words together, like “More milk.””"}]},{"lo":24,"hi":29,"items":[{"n":24,"text":"يبدأ بلعبة تبادل الأدوار أو روتين اجتماعي","how":"اسأل الوصي إذا كان الطفل يلعب لعبة أو لديه روتين لعب باستخدام كرة، بطانية، أو دبدوب في المنزل.\n\nإذا كان الأمر كذلك، اطلب من الوصي اختيار واحدة وبدء اللعب بها.\n\nالتقييم:\nوجود مثال واحد على نشاط يبدأه الطفل معك أو مع الوصي أو شخص آخر.","image":false},{"n":25,"text":"يستخدم الكلمات لأداء وظائف برغماتية متعددة","how":"ضع وجبة خفيفة مقدمة من الوصي أو لعبة صغيرة داخل كيس بلاستيكي شفاف وأغلقه. قدم الكيس للطفل وانتظر لترى ما إذا كان يستخدم الكلمات ليطلب منك فتح الكيس. اختيارياً، قم بتشغيل لعبة اللف، وعندما تتوقف، انتظر لترى ما إذا كان الطفل يستخدم الكلمات ليطلب منك إعادة لف اللعبة.\n\nأمثلة تقريبية على الوظائف البرغماتية:\n- \"أعطني\" (يطلب أفعالاً أو أشياء)\n- \"كرة\" (يذكر أسماء أفعال أو أشياء)\n- \"مزيد\" (يطلب التكرار)\n- \"ساعدني\" (يطلب المساعدة)\n- يهز/يومئ برأسه (يجيب عن أسئلة بنعم/لا)\n- \"ماما!\" (يستخدم كلمة لجذب الانتباه)\n\nالتقييم:\n- يستخدم الكلمات للتعبير عن خمس وظائف برغماتية مختلفة\n\nملاحظة:\nيتم تقييم الوظيفة البرغماتية بغض النظر عن دقة النطق أو اكتمال الكلمة.","image":false},{"n":66,"text":"يستخدم نحو 50 كلمة","how":"الإجراء:\nاطلب من المُرافق تعداد الكلمات التي يقولها الطفل: الطعام، الألعاب، الحيوانات، أجزاء الجسم، الأشخاص.\n\nالتقييم:\nيذكر المُرافق نحو 50 كلمة يقولها الطفل من تلقاء نفسه. يُقبل النطق غير الدقيق إذا كانت الكلمة ثابتة المعنى.","image":false,"added":true,"source":"ASHA, Communication Milestones 19–24 months: “Uses and understands at least 50 different words for food, toys, animals, and body parts.” CDC/AAP (Zubler et al., 2022), by 30 months: “Says ~50 words” Vocabulary lists in Arabic: Abdelwahab et al. (2021), Arabic CDI, including the Syrian dialect."},{"n":67,"text":"يستخدم الضمائر (أنا، إنت)","how":"الإجراء:\nأثناء اللعب، اسأل: «مين بدو الطابة؟» و«مين رح يلعب هلق؟» وأعطِ دوراً للطفل ولنفسك.\n\nالتقييم:\nيستخدم «أنا» أو «إنت» للإشارة الصحيحة مرتين، في اللعب أو حسب مثال من المُرافق.","image":false,"added":true,"source":"ASHA, Communication Milestones 19–24 months: “Uses words like me, mine, and you.” CDC/AAP (Zubler et al., 2022), by 30 months: “Says words like I, me, or we”"}]},{"lo":30,"hi":35,"items":[{"n":26,"text":"يستخدم الكلمات أكثر من الإيماءات للتواصل","how":"سؤال مراقبة:\nعندما يرغب طفلك في شيء ما، كيف يعبر عن ذلك؟ هل يستخدم الكلمات أكثر من الإشارات مثل الإشارة، محاولة الوصول إلى الشيء، أو سحب الملابس؟\n\nخيارات الإجابة:\na. لا يستخدم لا كلمات ولا إيماءات\nb. يستخدم الإيماءات فقط\nc. يستخدم الإيماءات أكثر من الكلمات في التواصل\nd. يستخدم الإيماءات والكلمات بنفس المعدل\ne. يستخدم الكلمات أكثر من الإيماءات في التواصل\n\nالتقييم:\nيستخدم الكلمات أكثر من الإيماءات في التواصل (اختيار e)","image":false},{"n":27,"text":"يُسمي أشياء في الصور","how":"أشر إلى كل صورة وقل: \"انظر إلى هذه الصورة. ما هذا؟\"\n\nقائمة الصور:\n- كرة\n- طفل\n- طائر\n- بسكويت\n- حذاء\n- كلب / جرو\n- بالون\n- ملعقة\n- تفاحة\n- قطة / هرة\n\nالتقييم:\n- يُسمي الطفل خمس صور بشكل صحيح\n\nملاحظة:\nيتم قبول أي نطق معتاد للطفل للإشارة إلى الشيء (مثلاً: مياو للقطة، عوعو للكلب) ولا يُشترط النطق الكامل","image":true},{"n":68,"text":"يقول اسمه عند سؤاله","how":"الإجراء:\nاسأل: «شو اسمك؟»\n\nالتقييم:\nيقول اسمه الأول. يُقبل النطق غير الدقيق إذا تعرّف المُرافق عليه.","image":false,"added":true,"source":"ASHA, Communication Milestones 2–3 years: “Says their name when asked.” CDC/AAP (Zubler et al., 2022), by 3 years: “Says first name when asked”"},{"n":69,"text":"يسأل مستخدماً أدوات الاستفهام (مين، شو، وين، ليش)","how":"الإجراء:\nضع غرضاً غريباً داخل كيس، أو أخفِ لعبة، وانتظر. اسأل المُرافق عن أسئلة يطرحها الطفل في البيت.\n\nالتقييم:\nيطرح سؤالين بأداتي استفهام مختلفتين، بالملاحظة أو بمثال من المُرافق.","image":false,"added":true,"source":"CDC/AAP (Zubler et al., 2022), by 3 years: “Asks who, what, where, or why questions, like “Where is mommy/daddy?”” ASHA, Communication Milestones 2–3 years: “Asks why and how.” Arabic: Hamdan & Hamdan (2020) found questions about concrete things come before abstract ones, with mi:n ranked easiest in its set."},{"n":70,"text":"يقول ما يحدث في الصورة (يسمي الفعل)","how":"الإجراء:\nاعرض صوراً لأشخاص يقومون بأفعال: يركض، يأكل، يلعب، ينام. اسأل: «شو عم يعمل؟»\n\nالتقييم:\nيسمي الفعل في ثلاث صور من أربع. لا يكفي تسمية الشخص أو الشيء.","image":false,"added":true,"source":"CDC/AAP (Zubler et al., 2022), by 3 years: “Says what action is happening in a picture when asked, like running, eating, or playing”"},{"n":71,"text":"يتحدث بتبادلين على الأقل في حوار","how":"الإجراء:\nابدأ حديثاً عن شيء يهتم به الطفل، مثل لعبته أو ما يفعله الآن، وانتظر رده.\n\nالتقييم:\nيستمر الحوار تبادلين كلاميين على الأقل حول الموضوع نفسه، مرة واحدة.","image":false,"added":true,"source":"CDC/AAP (Zubler et al., 2022), by 3 years: “Talks with you in conversation using at least 2 back-and-forth exchanges”"}]},{"lo":36,"hi":41,"items":[{"n":28,"text":"يستخدم تراكيب لفظية مختلفة","how":"1. تركيب: اسم/ضمير + فعل\n(مثل: noun/pronoun + verb)\nالوصف: تركيب يتكون من اسم أو ضمير يليها فعل، يشير إلى من يفعل الفعل وما هو الفعل\n\nصحيح:\n- السيارة تمشي\n- أنت تفتح الباب\nغير صحيح:\n- سيارة (اسم فقط)\n- أفتح (فعل فقط)\n\n2. تركيب: فعل + ضمير/اسم\n(verb + noun/pronoun)\nالوصف: الفعل يأتي أولًا ثم الضمير أو الاسم الذي يتم عليه الفعل\n\nصحيح:\n- أطعم الكلب\n- أمسكني\nغير صحيح:\n- أكل (دون مفعول به)\n- أمسَك (دون ذكر الضمير أو الاسم)\n\n3. تركيب: اسم/ضمير + فعل + مكان\n(noun/pronoun + verb + location)\nالوصف: الجملة تحتوي على فاعل وفعل مع تحديد مكان حدوث الفعل\n\nصحيح:\n- الطفل يجلس هنا\n- نلعب في الحديقة\nغير صحيح:\n- الولد البيت في يلعب (ترتيب الكلمات غير سليم)\n- البنت (غير مكتملة)\n\n4. تركيب: اسم/ضمير + فعل + صفة (وأحيانًا اسم إضافي)\n(noun/pronoun + verb + adjective [+ optional noun])\nالوصف: الجملة تصف حالة الفاعل أو شيء مرتبط به عبر صفة.\n\nصحيح:\n- الطفل متعب\n- القطة أكلت كثيرًا\nغير صحيح:\n- أسود جرو يلعب (ترتيب غير صحيح)\n- جرو يأكل أكثر (غير واضحة أو ناقصة)\n\n5. تراكيب الملكية أو الإضافة (مثل اسم + اسم)\npossession\n\nالوصف: تركيب يعبر عن الملكية أو العلاقة بين كلمتين\n\nصحيح:\n- كرة أبي\n- حقيبتي\nغير صحيح:\n- ماما عصير (ترتيب غير سليم جداً، والصحيح: عصير ماما)\n- حقيبة (غير مكتملة)\n\nفي المجمل: الجمل الصحيحة تحوي على فعل وفاعل على الأقل، والتراكيب تكون مرتبة بشكل طبيعي حسب قواعد اللغة العربية. أما الجمل غير الصحيحة فهي إما مفردات فقط، أو ترتيبها خاطئ، أو ناقصة.\n\nالتقييم: يُنتج الطفل ثلاث تراكيب لفظية مختلفة","image":false},{"n":29,"text":"ينتج جمل من ثلاثة أو أربعة كلمات في الكلام التلقائي","how":"قدم للطفل عدة ألعاب وأشياء وضعها أمامه وشجعه على اللعب. خلال اللعب، تحدث مع الطفل.\n\nأمثلة تقريبية على التراكيب الشائعة في هذا العمر:\n- \"آنا اشرب عصير\" (ضمير + فعل + اسم)\n- \"الولد يلعب بالطابة\" (اسم + فعل + اسم)\n- \"ماما تقرأ قصة جديدة\" (اسم + فعل + اسم + صفة)\n- \"أين السيارة الحمراء؟\" (أداة استفهام + اسم + صفة)\n- \"البطة في الماء\" (اسم + حرف جر + اسم)\n\nالتقييم:\n- يُكوّن الطفل ثلاث جمل تحتوي على 4-3 كلمات لغوية مختلفة.\n\nملاحظة:\nعدد الكلمات في جملته هو الذي يتم حسابه بغض النظر عن نوع التركيب اللغوي.","image":false},{"n":30,"text":"يستخدم صيغة فعل المضارع","how":"تدريب:\n- بنت تلعب\n- بنت تاكل\n- ولد ياكل\n- بنت تشرب\n- ولد يشرب\n- عيلة ياكلوا\n\nالتقييم: إجابتان صحيحتان","image":true},{"n":72,"text":"ينفي بالكلام (ما، مو، مش)","how":"الإجراء:\nأعطِ الطفل طابة واسأل: «هاد كتاب؟» ثم اعرض كوباً فارغاً واسأل: «فيه مي؟» ثم «الكلب بيطير؟»\n\nالتقييم:\nيستخدم أداة نفي في جملة («ما فيه»، «مو كتاب») مرتين. لا تكفي كلمة «لا» وحدها.","image":false,"added":true,"source":"Arabic research: Developmental Trajectories of Verbal and Verbless Negation in Jordanian Arabic, Psycholinguistics 2025;38(1):41–76. 56 typically developing children aged 3–9; preverbal negation was acquired earliest. Age band is proposed from the youngest group studied; the pilot data must confirm it."}]},{"lo":42,"hi":47,"items":[{"n":31,"text":"يستخدم صيغة جمع","how":"تدريب: تفاحات\n\nقائمة الكلمات:\n- سيارات\n- طابات\n- بالونات\n- شجرات\n- سمكات\n- طيارات\n\nالتقييم:\n- يجيب الطفل بأربع إجابات صحيحة\n\nملاحظة:\nيتم قبول أي صيغة جمع منطقية للكلمة حتى لو لم تكن الصيغة الفصحى الدقيقة","image":true},{"n":32,"text":"يستخدم أدوات الملكية","how":"تدريب: هي موزة الولد هي موزتو وهي موزتها\n\nأمثلة:\n- طابتها / طعامها\n- طابتو / طعامو\n- كلبو / قطتها\n- كلبها / قطتها\n\nالتقييم:\n- يجيب الطفل بثلاث إجابات صحيحة\n\nملاحظة:\nيتم قبول صيغ الملكية المستخدمة في اللهجة المحلية للطفل","image":true},{"n":33,"text":"يصف كيفية استخدام الشيء","how":"تمرين: انظر إلى هذه الصورة. هذا قلم رصاص. ماذا تفعل بالقلم الرصاص؟ (تكتب به، ترسم به)\n\nالأشياء المطلوبة:\n- فرشاية\n- ملعقة\n- سكين\n- منشفة\n- جرابات\n- طنجرة\n\nالتقييم:\n- يصف الطفل استخدام أربعة أشياء بشكل صحيح\n\nملاحظة:\nيتم قبول أي وصف منطقي لاستخدام الشيء حتى لو لم يكن الاستخدام الأساسي له","image":true},{"n":73,"text":"يستخدم كلمات المكان (في، على، تحت)","how":"الإجراء:\nضع لعبة داخل الصندوق، ثم عليه، ثم تحته، واسأل كل مرة: «وين اللعبة؟»\n\nالتقييم:\nيذكر كلمة المكان الصحيحة في إجابتين. الإشارة وحدها لا تُحسب.","image":false,"added":true,"source":"ASHA, Communication Milestones 3–4 years: “Understands and uses more location words, like inside, on, and under.”"},{"n":74,"text":"يحكي شيئاً حدث معه اليوم","how":"الإجراء:\nاسأل: «شو عملت اليوم؟» أو «مين شفت اليوم؟» واسأل المُرافق إن كان ما قاله صحيحاً.\n\nالتقييم:\nيذكر حدثاً واحداً حقيقياً من يومه بجملة.","image":false,"added":true,"source":"CDC/AAP (Zubler et al., 2022), by 4 years: “Talks about at least 1 thing that happened during his day, like “I played soccer.””"},{"n":75,"text":"يقول كلمات من أغنية أو قصة أو أنشودة","how":"الإجراء:\nاسأل المُرافق عن أغنية يحبها الطفل. ابدأ بها أو بقصة مألوفة وتوقف قبل كلمة معروفة، وانتظر.\n\nالتقييم:\nيقول بعض الكلمات من الأغنية أو القصة أو الأنشودة.","image":false,"added":true,"source":"CDC/AAP (Zubler et al., 2022), by 4 years: “Says some words from a song, story, or nursery rhyme”"}]},{"lo":48,"hi":53,"items":[{"n":34,"text":"يستخدم صيغة جمع تكسير","how":"تدريب: قطط\n\nقائمة الكلمات المفرد:\n- كلاب (كلب)\n- اصابع (إصبع)\n- موز (موزة)\n- الوان (لون)\n- عيون (عين)\n\nالتقييم:\n- يجيب الطفل بأربع إجابات صحيحة\n\nملاحظة:\nيتم قبول أي صيغة جمع تكسير مستخدمة في اللهجة المحكية حتى لو اختلفت عن الفصحى","image":true},{"n":35,"text":"ينتج صيغة المثنى","how":"تمرين: قلم قلمين\n\nأمثلة:\n- سيارتين\n- قلمين\n- تفاحتين\n- بابين\n\nالتقييم:\n- يجيب الطفل بثلاث إجابات صحيحة\n\nملاحظة:\nيتم قبول صيغ المثنى المستخدمة في اللهجة المحلية للطفل","image":true},{"n":36,"text":"يجيب عن الأسئلة بمنطق","how":"تمرين: ماذا تفعل عندما تشعر بالجوع؟ (تأكل)\n\nأسئلة:\n- ماذا تفعل إذا كانت يداك متسختين؟ (غسلهم)\n- ماذا تفعل عندما تشعر بالبرد؟ (البس)\n- ماذا تفعل عندما تشعر بالتعب؟ (نام)\n\nالتقييم:\n- يجيب الطفل بإجابتين صحيحتين\n\nملاحظة:\nيتم قبول أي إجابة منطقية حتى لو لم تكن الكلمة دقيقة","image":false},{"n":37,"text":"ينتج توافق الجنس","how":"أمثلة توافق الجنس:\n1. اسم مع فعل (ولد ياكل/بنت تاكل)\n2. اسم مع صفة (ولد طويل/بنت طويلة)\n3. صفة لون (قلم احمر/وردة صفرا)\n4. اسم اشارة مع اسم (هذا ولد/هي بنت)\n\nمجموعة 1:\n- ولد يشرب / بنت (تشرب)\n- ولد (يلعب) / بنت تلعب\n- ولد يكتب / بنت (تكتب)\n- ولد (يمشط) / بنت تمشط\n\nمجموعة 2:\n- فيل كبير / فارة صغيرة\n- دجاجة كبيرة / صوص (صغير)\n- زرافة طويلة / ولد (قصير)\n- زرافة طويلة / بنت (قصيرة)\n- عصفور احمر / سيارة (حمرا)\n- فليفلة صفرا / باص (اصفر)\n\nمجموعة 3:\n- هذا ولد / هي بنت\n- هذا ديك / (هي) دجاجة\n- هذا تور / (هي) بقرة\n- (هذا) باص / هي سيارة\n\nالتقييم:\n- يجيب الطفل بثلاث إجابات صحيحة في كل مجموعة\n\nملاحظة:\nيتم قبول الصيغ المستخدمة في اللهجة المحلية","image":true},{"n":38,"text":"ينتج توافق العدد مع الاسم","how":"1. عدد مع اسم اشارة\n   - هذه ولد / هدول اولاد\n   - هذه بنت / هدول بنات\n\n2. عدد مع جمع\n   - بالون واحد / خمس بالونات\n   - سمكة وحدة / ثلاث سمكات\n\nالتقييم:\n- يجيب الطفل بإجابة صحيحة لكل بند\n\nملاحظة:\nيتم قبول صيغ الجمع المستخدمة في اللهجة المحلية","image":true}]},{"lo":54,"hi":59,"items":[{"n":39,"text":"يجيب عن أسئلة ماذا، أين، ومتى","how":"الجزء الآول:\n- شو عم يعمل الولد؟\n- وين الولاد؟\n- ايمت نام/فاق الولد؟\n\nالجزء الثاني:\n- ماذا أكلت في الإفطار؟\n- أين أكلت الإفطار؟\n- متى تنظف أسنانك؟\n- متى تذهب إلى النوم؟\n\nالتقييم:\nثلاث إجابات صحيحة من الجزء الثاني/ الجزء الآول تدريب","image":true},{"n":40,"text":"يستخدم زمن الفعل الماضي","how":"تمرين:\nولد يغسل / ولد غسل وخلص\n\nأمثلة:\n- غسلت\n- لبس\n- لبست\n\nالتقييم:\nإجابتان صحيحتان\n\nملاحظة:\nلا تعاقب إذا استخدم الطفل فعلًا غير الفعل المستهدف طالما أن زمن الفعل صحيح والمنطوق معقول","image":true},{"n":41,"text":"يكمل المقارنة والمشابهة","how":"تمرين: أرني يدك. انتظر حتى يفعل الطفل ذلك، ثم ضع يدك بجانب يد الطفل.\nقل: يدي كبيرة. يدك... (صغيرة)\n\n- أجلس على الكرسي؛ أنام في...\n- الخبز للأكل؛ الحليب لـ...\n- النملة صغيرة؛ الفيل...\n- التلج بارد؛ النار...\n- الليل مظلم؛ النهار...\n- السمك يسبح؛ الطائر...\n- الأسد قوي؛ الفأر...\n- الليمون حامض؛ السكر...\n- السيارة سريعة؛ السلحفاة...\n- الصيف حار؛ الشتاء...\n\nالتقييم: \nثماني إجابات صحيحة","image":false},{"n":76,"text":"يستخدم كلمات الزمن (مبارح، بكرا)","how":"الإجراء:\nاسأل: «شو عملت مبارح؟» و«شو رح تعمل بكرا؟» وكمّل: «اليوم الأحد، بكرا...» بحسب اليوم الفعلي.\n\nالتقييم:\nيستخدم «مبارح» و«بكرا» بمعناهما الصحيح في حديثه. يُقبل غير دقيق الأحداث إذا كان الزمن صحيحاً.","image":false,"added":true,"source":"ASHA, Communication Milestones 4–5 years: “Uses more words for time—like yesterday and tomorrow—correctly.”"},{"n":77,"text":"يسمّي 10 حروف أو أكثر","how":"الإجراء:\nاعرض الحروف العربية مكتوبة واحداً واحداً، واسأل: «شو هاد الحرف؟»\n\nالتقييم:\nيسمّي 10 حروف بشكل صحيح.\n\nملاحظة: تتأثر هذه المهارة بالتعرض للحضانة. سجّل ذلك في الملاحظة.","image":false,"added":true,"source":"ASHA, Communication Milestones 4–5 years: “Recognizes and names 10 or more letters and can usually write their own name.”"},{"n":78,"text":"يدمج مقطعين ليكوّن كلمة","how":"تمرين: «كِ... تاب. شو الكلمة؟» (كتاب)\n\nقل المقطعين بينهما توقف ثانية:\n١. با... ب\n٢. قَ... لَم\n٣. مَ... وز\n٤. سَ... مَك\n\nالتقييم:\nثلاث إجابات صحيحة.","image":false,"added":true,"source":"ASHA, Communication Milestones 4–5 years: “Blends word parts, like cup + cake = cupcake.” Adapted: Arabic has few compound words of this kind, so this uses syllables."}]},{"lo":60,"hi":65,"items":[{"n":42,"text":"يسمي حسب الوصف","how":"تمرين: ما هو الحيوان الذي يطارد الفئران وله شوارب؟ يصدر صوت مواء. (قط)\n\n- ما هي اللعبة الدائرية التي ترتد؟ تستخدمها للرمي والقبض عليها.\n- ماذا تستخدم عندما تنتهي من الاستحمام أو تخرج من الدش؟ تستخدمه لتجفيف نفسك.\n- ماذا تستخدم عندما تريد أن ترسم شيئًا؟ تأتي في علبة.\n\nالتقييم: إجابتان صحيحتان\n\nإضافي:\n- ما هو الشيء الذي يضيء في الليل ويراه الناس من بعيد؟\n- ما هو الشيء الذي تلبسه في قدميك عندما تخرج من المنزل؟\n- ما هو الشيء الذي تستخدمه لتقطيع الخيار والبندورة؟\n- ما هو الشيء الذي يخرج من الدجاجة ويأكله الناس؟\n- ما هو الشيء الذي يغطي جسمك عندما تنام في الليل؟","image":false},{"n":43,"text":"يجيب عن أسئلة تتعلق بأحداث افتراضية","how":"تمرين: ماذا تفعل إذا لم تستطع إيجاد حذائك في الصباح؟\n\n- ماذا تفعل إذا شعرت بالمرض؟\n- ماذا تفعل إذا سقطت؟\n- ماذا تفعل إذا أردت اللعب بلعبة صديقك؟\n\nالتقييم: إجابتان صحيحتان\n\nإضافي:\n- ماذا تفعل إذا جعت؟\n- ماذا تفعل إذا انكسرت لعبتك؟\n- ماذا تفعل إذا عطشت؟","image":false},{"n":44,"text":"يسمي فئات المفاهيم","how":"تمرين: استمع، كلب، قط، حصان، بقرة، ماعز. كل هذه حيوانات.\n\n- خبز، فاصوليا، تفاح، أرز. كل هذه...\n- ماء، حليب، عصير، صودا. كل هذه...\n- قميص، فستان، بنطلون، جوارب. كل هذه...\n\nالتقييم: إجابتان صحيحتان\n\nإضافي:\n- تفاح، موز، عنب، برتقال. كل هذه...\n- جزر، خيار، طماطم، بطاطس. كل هذه...\n- عصفور، بطة، نسر، حمامة. كل هذه...\n- كرة، دمية، مكعبات، سيارة لعبة. كل هذه...\n- أحمر، أزرق، أصفر، أخضر. كل هذه...\n- قطة، كلب، أرنب، هرة. كل هذه...","image":false}]},{"lo":66,"hi":71,"items":[{"n":45,"text":"يجيب على أسئلة \"لماذا\" بتقديم سبب","how":"تمرين:\n- لماذا نلبس الأحذية؟\n- لماذا ننام؟\n- لماذا نأكل؟\n- لماذا نغسل أيدينا؟\n\nالتقييم:\nإجابتان صحيحتان\n\nملاحظة:\nيتم قبول أي إجابة منطقية توضح سببًا صحيحًا حتى لو لم تكن الصيغة اللغوية دقيقة","image":false},{"n":46,"text":"يكرر الجمل التي يسمعها","how":"تمرين:\nاستمع وقل ما أقول.\n\nالجمل المطلوبة:\n1. \"أنا أحب الشوكولاتة\"\n2. \"هل تعطيني شيئًا لأشرب؟\"\n3. \"الطفلة التي تغني هي أختي\"\n4. \"هل يمكن لأصدقائي القدوم لمشاهدة التلفاز؟\"\n5. \"عندما عاد من المدرسة، أكل سامي تفاحة\"\n\nالتقييم:\n- يكرر الطفل إجابتين صحيحتين\n\nملاحظة:\nيتم قبول التكرار مع وجود أخطاء طفيفة في النطق طالما ظلت الجمل مفهومة","image":false}]},{"lo":72,"hi":83,"items":[{"n":47,"text":"يسرد القصة بتتابع منطقي","how":"تمرين:\n1. كان هناك أخوان يلعبان كرة السلة، وقال الأخ الأكبر، أنت لن تسجل أي سلة أبدًا!\n2. أخذ الأخ الأصغر الكرة ورمى بها عالياً قدر استطاعته.\n3. أوه! تعثر الأخ الأصغر وسقط، ولكن الكرة رغم ذلك دخلت السلة.\n\nقصة 2:\n1. كان يبحث عن دبه.\n2. \"ماما، هل تعرفين أين دبي؟\"\n3. وكان يبحث عن الدب في كل مكان.\n4. ماما وجدت الدب.\n\nالتقييم:\n- يصف الطفل جميع الصور بتتابع منطقي\n\nملاحظة:\nالتسلسل الصحيح للقصة هو ١-٢-٣-٤ أو ١-٣-٢-٤. لا يشترط أن تكون وصف كل صورة جملة كاملة أو صحيحة نحويًا للحصول على النقاط عن التسلسل.","image":true},{"n":48,"text":"يسرد القصة باستخدام جمل صحيحة نحويًا","how":"تمرين:\n1. كان يبحث عن دبه.\n2. \"ماما، هل تعرفين أين دبي؟\"\n3. وكان يبحث عن الدب في كل مكان.\n4. ماما وجدت الدب.\n\nالتقييم:\n- يستخدم الطفل ثلاث جمل صحيحة نحويًا أو أكثر تصف الأفعال في الصور.\n\nملاحظة:\nيجب أن تكون كل جملة صحيحة نحويًا وأن تتوافق مع الفعل الظاهر في كل صورة من الصور. عند سرد الطفل للقصة، يجب أن يتضمن إشارات على الأقل للصورة الأولى.","image":true},{"n":49,"text":"يصحح السخافة اللغوية (اللغة الدلالية)","how":"تمرين:\n1. انت ولد؟ (اذا كانت بنت)\n2. موزة لونها احمر؟\n3. القطة بتعمل عوو؟\n\nأمثلة أخرى:\n- الولد أكل سيارة كبيرة.\n- الفتاة تأكل معكرونة بحذاء.\n- الولد ينام على دراجة هوائية.\n\nالتقييم:\n- إجابتين صحيحتين\n\nملاحظة:\nلا يشترط أن يكون الرد صحيحًا نحويًا شرط أن يكون البناء الجديد مناسبًا دلاليًا.","image":false},{"n":50,"text":"يعيد سرد قصة مع مقدمة","how":"1. الطفلان لديهما كلب اسمه لولو.\n2. آحمد ومايا شافوا لولو برا تحت المطر.\n3. الكلب يحتاج إلى منزل.\n4. لولو تبلل بالكامل تحت المطر.\n5. الطفلان سيصنعان منزلًا.\n\nالتقييم:\n- الطفل يقدم القصة/الشخصيات (بما في ذلك الكلب والأطفال) من الجزء الأول من القصة.","image":true},{"n":51,"text":"يعيد سرد قصة بأربعة أحداث متسلسلة","how":"التقييم:\n- الطفل يصف أربعة أحداث على الأقل من أجزاء القصة بترتيب صحيح\n- ينبغي أن يستخدم الطفل كلمات مثل \"ثم\" أو \"بعد ذلك\" أو \"لذا\".\n\nملاحظة:\nيجب ألا يكتفي الطفل بتسمية الفعل في كل صورة فقط.","image":true},{"n":52,"text":"يعيد سرد قصة بخاتمة منطقية","how":"1. الآن عندما تمطر، لا يبتل لولو.\n2. لولو جاف ودافئ عندما تمطر الآن.\n3. النهاية.\n4. لولو سعيد.\n5. لولو نائم في منزله الصغير.\n\nالتقييم:\n- يجب أن تتضمن إعادة السرد خاتمة منطقية تشمل معلومات من الجزء الثامن من القصة.\n- لا يتضمن بوصف الفعل الأخير فقط دون تعليقات ختامية.","image":true},{"n":53,"text":"يكمل أوجه الشبه","how":"تمرين:\n- فكر في شيء شديد السخونة. (الشمس/النار/الشمعة)\n\nأمثلة:\n1. إذا كان شيء ما شديد البرودة، بارد.\n2. إذا كان شيء ما حادًا جدًا،\n3. إذا كان شيء شيئًا أخضر جدًا،\n\nإضافي:\n4. إذا كان شيء ما كبيرًا جدًا،\n5. إذا كان شيء ما سريعًا جدًا،\n6. إذا كان شيء ما لينًا جدًا،\n\nالتقييم:\n- يجب أن يكون هناك إجابتان صحيحتان على الأقل","image":false}]},{"lo":84,"hi":95,"items":[{"n":54,"text":"يصف أوجه التشابه","how":"تمرين:\n- شبه بين كرسي وكلب\n\nأمثلة:\n1. كيف يشبه الطائرة والطيور بعضهما البعض؟\n2. كيف يشبه الشمس والقمر بعضهما البعض؟\n3. كيف يشبه الحجر والطوبة بعضهما البعض؟\n4. كيف يشبه الحليب والعصير بعضهما البعض؟\n\nالتقييم:\n- ثلاث إجابات صحيحة منطقية\n\nملاحظة:\nلا يجب أن تكون الإجابة جملة كاملة أو صحيحة نحويًا للحصول على درجة صحيحة.","image":true},{"n":55,"text":"ينتج صيغة المضارع المنصوب","how":"أمثلة:\n1. الطفل لا يريد أن يأكل. أمه تريد منه أن... (يأكل)\n2. هي لا ترغب في القفز. لا أعتقد أن... (تقفز)\n3. الطفل الطويل يصل إلى التفاحة. لا أعتقد أن هذا الطفل... (يحتاج مساعدة)\n4. هذا الطفل يرسم. ليس لديه ورقة. لا أعتقد أنه... (يستطيع الرسم)\n5. هذه الفتاة بحاجة إلى مساعدة. تريد من أمها أن... (تساعدها)\n\nمعلومات إضافية:\nأدوات نصب المضارع:\n- أَنْ (من أجل) = أريد أن ألعبَ\n- لِـ (من أجل) = درست لِأنجح\n- حَتَّى = تعبت حتى وصلت\n- لَنْ (نفي المستقبل) = لن أذهب\n- إِذَنْ (النتيجة) = إذن نذهب\n\nالتقييم:\n- ثلاث إجابات صحيحة\n\nملاحظة:\nيتم قبول أي فعل مضارع منصوب منطقي في السياق حتى لو لم يكن الفعل المتوقع، مع مراعاة استخدام أدوات النصب المناسبة","image":true},{"n":56,"text":"يشكل جملة من مفردات (صياغة جمل)","how":"تدريب ١:\n- دورك: \"الآن كوّن جملة باستخدام كلمتي 'كلب' و'قطة'.\"\n\nتدريب ٢:\n- دورك: \"الآن كوّن جملة باستخدام الكلمات: 'بسكويت'، 'أخوات'، و'كتير'.\"\n\nأمثلة أخرى:\n- ولد، بسكليت\n- المدرسة، الولد\n- بنت، ما، شافت\n\nالتقييم:\n- إجابتان صحيحتان\n\nملاحظة:\nيجب أن تكون الجملة التي يصوغها الطفل صحيحة من حيث المعنى والقواعد، وتحتوي على جميع الكلمات المستهدفة.","image":true},{"n":57,"text":"ينتج مرادفات للكلمات","how":"أمثلة:\n- ولد غاضبًا: معصب\n- أعطيت أمي زهرة الجميلة: حلوة\n- كان علي يبدو غير سعيد: حزين\n- كان اللغز بسيطًا: سهل\n\nإضافي:\n- سلحفاة تمشي ببطء\n- ولد ذكي\n- بنت فرحانة\n\nالتقييم:\n- ثلاث إجابات صحيحة\n\nملاحظة:\nلا يلزم أن تكون الإجابات صحيحة نحويًا (مثل توافق الصفة مع الاسم) لمنح الدرجة.","image":true},{"n":58,"text":"يستخدم مفاهيم كمية ( أكثر من )","how":"تمرين:\n- هاد الولد (اصغر من / اكبر من)\n\nأمثلة أخرى:\n- اكثر من / اقل من\n- اطول من / اقصر من\n\nالتقييم:\n- إجابتان صحيحتان","image":true},{"n":59,"text":"ينتج كلمة جديدة من كلمة تم حذف صوت منها (وعي فونولوجي)","how":"أمثلة:\n- باب = اب\n- بحر = بر\n- شمع = شم\n\nتدريبات:\n1. كلب = لب\n2. صبح = صح\n3. تمر = تم\n\nالتقييم:\n- إجابتان صحيحتان","image":false},{"n":60,"text":"ينتج كلمات تتناغم مع الكلمة التي يسمعها (وعي فونولوجي)","how":"أمثلة:\n- شم (سم/عم/فم/دم)\n- قلب (لعب/كلب/حلب/صلب)\n- تمر (نمر/زمر/حمر/جمر)\n\nتدريب:\n- قرد / فرد / ورد / برد / نرد\n\nالتقييم:\n- إجابتان صحيحتان","image":false},{"n":61,"text":"ينتج مفاهيم الزمن والتسلسل (متأخر، قبل)","how":"أمثلة:\n1. وصل هذا الولد إلى المدرسة مبكرًا. وصل هذا الولد إلى المدرسة... (متأخرًا، متأخر عن المدرسة، لاحقًا)\n2. فرشت الفتاتان أسنانهما في الصباح. فرشت هذه الفتاة أسنانها بعد أن ارتدت ملابسها للمدرسة، ولكن هذه الفتاة فرشت أسنانها... (قبل، قبل أن ترتدي ملابسها للمدرسة، قبل المدرسة)\n\nالتقييم:\n- إجابتان صحيحتان","image":true}]}]};if(typeof module!=='undefined')module.exports=data;else root.ACEC_DATA=data;})(this);
